window.ETSDATA=window.ETSDATA||{};window.ETSDATA[5]={"lc":{"p1":[{"n":1,"opts":["She's pushing a large container down a hallway.","She's looking at information on a laptop screen.","She's sorting through paper files.","She's placing a hat on top of a file cabinet."],"vi":["Cô ấy đang đẩy một container lớn xuống hành lang.","Cô ấy đang xem thông tin trên màn hình laptop.","Cô ấy đang sắp xếp các tập hồ sơ giấy.","Cô ấy đang đặt một chiếc mũ lên trên tủ hồ sơ."],"ans":"C","a":"E26-T05-01.mp3","img":"q1.jpg"},{"n":2,"opts":["A worker is painting lines on the floor.","A worker is using a machine to move some boxes.","A worker is sealing some packages.","A worker is repairing a motor."],"vi":["Một công nhân đang vẽ/sơn các đường kẻ trên sàn.","Một công nhân đang dùng máy để di chuyển một số thùng hộp.","Một công nhân đang niêm phong/dán kín một số gói hàng.","Một công nhân đang sửa chữa một động cơ."],"ans":"B","a":"E26-T05-02.mp3","img":"q2.jpg"},{"n":3,"opts":["There are beverages available inside a tent.","There are some people riding in an automobile.","The man is reaching for a water bottle.","The woman is moving some furniture."],"vi":["Có đồ uống có sẵn bên trong một cái lều.","Có một số người đang ngồi trong xe hơi.","Người đàn ông đang với tay lấy một chai nước.","Người phụ nữ đang di chuyển một số đồ nội thất."],"ans":"A","a":"E26-T05-03.mp3","img":"q3.jpg"},{"n":4,"opts":["The door of a clothing store has been propped open.","Customers are waiting to enter a clothing store.","One of the customers is trying on a jacket.","Clothing is displayed outside on racks."],"vi":["Cửa của một cửa hàng quần áo đã được chống mở (mở toang ra).","Khách hàng đang chờ để vào cửa hàng quần áo.","Một trong những khách hàng đang thử một chiếc áo khoác.","Quần áo đang được trưng bày bên ngoài trên các giá treo."],"ans":"D","a":"E26-T05-04.mp3","img":"q4.jpg"},{"n":5,"opts":["One of the men is lowering some window shades.","One of the men is writing on a poster board.","One of the women is putting on a sweater.","One of the women is reading from a notebook."],"vi":["Một trong những người đàn ông đang hạ một số rèm cửa sổ xuống.","Một trong những người đàn ông đang viết lên bảng áp phích.","Một trong những người phụ nữ đang mặc áo len.","Một trong những người phụ nữ đang đọc từ cuốn sổ tay."],"ans":"B","a":"E26-T05-05.mp3","img":"q5.jpg"},{"n":6,"opts":["One of the cars is stopped at a stop sign.","Some tires are stacked against a building.","Some vehicles are being washed.","A motorcycle is going through a gate."],"vi":["Một trong những chiếc xe hơi đang dừng lại ở biển báo dừng.","Một số lốp xe được xếp chồng vào tường của một tòa nhà.","Một số phương tiện đang được rửa.","Một chiếc xe máy đang đi qua cổng."],"ans":"B","a":"E26-T05-06.mp3","img":"q6.jpg"}],"p2":[{"n":7,"q":"Where did you put the invoice from Stanson Incorporated?","qvi":"Bạn đã đặt hóa đơn từ Stanson Incorporated ở đâu?","opts":["No, not yet.","On your desk.","The post office is crowded today."],"vi":["Không, vẫn chưa.","Trên bàn làm việc của bạn.","Bưu điện hôm nay đông đúc lắm."],"ans":"B","a":"E26-T05-07.mp3"},{"n":8,"q":"Is the inspector coming this afternoon or tomorrow morning?","qvi":"Thanh tra viên sẽ đến chiều nay hay sáng mai?","opts":["The exterior light isn't working.","He'll be here tomorrow.","I'll take the next right turn."],"vi":["Đèn bên ngoài không hoạt động.","Ông ấy sẽ đến đây vào ngày mai.","Tôi sẽ rẽ phải ở ngã rẽ tiếp theo."],"ans":"B","a":"E26-T05-08.mp3"},{"n":9,"q":"What's the total cost to remodel the office lobby?","qvi":"Chi phí tổng để cải tạo sảnh văn phòng là bao nhiêu?","opts":["The view from this window is great.","Over 50,000 dollars.","No, a sofa and table."],"vi":["Quang cảnh từ cửa sổ này tuyệt vời.","Hơn 50.000 đô la.","Không, một ghế sofa và bàn."],"ans":"B","a":"E26-T05-09.mp3"},{"n":10,"q":"Are you getting the same type of desk or a different one?","qvi":"Bạn đang mua cùng loại bàn làm việc hay loại khác?","opts":["It's conveniently located.","I can pick it up for you.","The same type."],"vi":["Nó nằm ở vị trí thuận tiện.","Tôi có thể lấy nó cho bạn.","Cùng loại."],"ans":"C","a":"E26-T05-10.mp3"},{"n":11,"q":"We're taking the clients to the theater this evening.","qvi":"Chúng tôi sẽ đưa khách hàng đến rạp hát tối nay.","opts":["He already ate.","I'll reserve a taxi.","From Australia."],"vi":["Anh ấy đã ăn rồi.","Tôi sẽ đặt taxi.","Từ Úc."],"ans":"B","a":"E26-T05-11.mp3"},{"n":12,"q":"When is your budget report due?","qvi":"Báo cáo ngân sách của bạn hạn chót là khi nào?","opts":["It was too expensive.","I don't need one.","By Tuesday at the latest."],"vi":["Nó quá đắt.","Tôi không cần.","Muộn nhất là thứ Ba."],"ans":"C","a":"E26-T05-12.mp3"},{"n":13,"q":"Who can I talk to about getting a membership at this fitness center?","qvi":"Tôi có thể nói chuyện với ai về việc đăng ký thành viên tại trung tâm thể dục này?","opts":["A monthly bill.","Some new workout equipment.","I can help you with that."],"vi":["Hóa đơn hàng tháng.","Một số thiết bị tập luyện mới.","Tôi có thể giúp bạn."],"ans":"C","a":"E26-T05-13.mp3"},{"n":14,"q":"Are you planning to buy a house in the city?","qvi":"Bạn có kế hoạch mua nhà ở thành phố không?","opts":["A housecleaning company.","I don't want to move.","I'll be waiting at the post office."],"vi":["Một công ty dọn nhà.","Tôi không muốn chuyển đi.","Tôi sẽ chờ ở bưu điện."],"ans":"B","a":"E26-T05-14.mp3"},{"n":15,"q":"How did you decide on a venue for the fund-raising event?","qvi":"Bạn đã quyết định địa điểm cho sự kiện gây quỹ như thế nào?","opts":["A small contribution.","I got a recommendation from a friend.","To buy books for the library."],"vi":["Một khoản đóng góp nhỏ.","Tôi nhận được lời giới thiệu từ bạn bè.","Để mua sách cho thư viện."],"ans":"B","a":"E26-T05-15.mp3"},{"n":16,"q":"Could you help Ms. Ishida update the expense reports?","qvi":"Bạn có thể giúp cô Ishida cập nhật báo cáo chi phí không?","opts":["It's an electric vehicle.","This restaurant is expensive.","I'll have time after my meeting."],"vi":["Đó là xe điện.","Nhà hàng này đắt đỏ.","Tôi sẽ có thời gian sau cuộc họp."],"ans":"C","a":"E26-T05-16.mp3"},{"n":17,"q":"The sales representatives really appreciated the training we led.","qvi":"Các đại diện bán hàng thực sự đánh giá cao buổi đào tạo chúng tôi dẫn dắt.","opts":["The new transportation center nearby.","No, but there is a manual online.","Yes, they seemed to find it helpful."],"vi":["Trung tâm giao thông mới gần đó.","Không, nhưng có hướng dẫn trực tuyến.","Có, họ dường như thấy nó hữu ích."],"ans":"C","a":"E26-T05-17.mp3"},{"n":18,"q":"Do you know who was promoted to senior director?","qvi":"Bạn có biết ai được thăng chức lên giám đốc cấp cao không?","opts":["It hasn't been announced yet.","I received my promotional gift yesterday.","I've seen that film."],"vi":["Nó chưa được công bố.","Tôi nhận quà khuyến mãi của mình hôm qua.","Tôi đã xem phim đó."],"ans":"A","a":"E26-T05-18.mp3"},{"n":19,"q":"Isn't the registration deadline tomorrow?","qvi":"Hạn chót đăng ký không phải là ngày mai sao?","opts":["Here's a map that you can use.","No, it's next week.","My office is on the ninth floor."],"vi":["Đây là bản đồ bạn có thể sử dụng.","Không, là tuần sau.","Văn phòng của tôi ở tầng chín."],"ans":"B","a":"E26-T05-19.mp3"},{"n":20,"q":"Would you like some help installing that new software?","qvi":"Bạn có cần giúp đỡ để cài đặt phần mềm mới không?","opts":["No, I'm sure we sent it out yesterday.","Thanks, but I know how to do it.","He can type very fast."],"vi":["Không, tôi chắc chúng tôi đã gửi nó hôm qua.","Cảm ơn, nhưng tôi biết cách làm.","Anh ấy có thể đánh máy rất nhanh."],"ans":"B","a":"E26-T05-20.mp3"},{"n":21,"q":"Our factory makes the best cookies in the city.","qvi":"Nhà máy của chúng tôi làm bánh quy ngon nhất thành phố.","opts":["A cup of sugar.","He worked an afternoon shift.","Aren't they delicious?"],"vi":["Một cốc đường.","Anh ấy làm ca chiều.","Chúng thật ngon đúng không?"],"ans":"C","a":"E26-T05-21.mp3"},{"n":22,"q":"The fruit market is still selling mangoes, isn't it?","qvi":"Chợ trái cây vẫn bán xoài, phải không?","opts":["No thanks—I don't need anything.","There's a waiting area in the lobby.","Yes, I bought some there yesterday."],"vi":["Không cảm ơn—Tôi không cần gì.","Có khu vực chờ ở sảnh.","Có, tôi mua một ít ở đó hôm qua."],"ans":"C","a":"E26-T05-22.mp3"},{"n":23,"q":"Why are you staying in the office for lunch?","qvi":"Tại sao bạn ở lại văn phòng ăn trưa?","opts":["No, they weren't.","Just a salad and soup, please.","Because it is raining."],"vi":["Không, chúng không phải.","Chỉ salad và súp thôi, làm ơn.","Vì trời đang mưa."],"ans":"C","a":"E26-T05-23.mp3"},{"n":24,"q":"How did the company basketball team play last night?","qvi":"Đội bóng rổ của công ty chơi thế nào tối qua?","opts":["Sure, I'll have a few.","How can I sign up?","The game was canceled."],"vi":["Chắc chắn, tôi sẽ lấy vài cái.","Tôi đăng ký thế nào?","Trận đấu bị hủy."],"ans":"C","a":"E26-T05-24.mp3"},{"n":25,"q":"Isn't our department's quarterly report supposed to be sent out today?","qvi":"Báo cáo hàng quý của bộ phận chúng ta không phải gửi hôm nay sao?","opts":["No, he drinks coffee.","There's a lot of information to include.","Some office supplies."],"vi":["Không, anh ấy uống cà phê.","Có nhiều thông tin cần bao gồm.","Một số vật dụng văn phòng."],"ans":"B","a":"E26-T05-25.mp3"},{"n":26,"q":"Would you like a copy of the article I mentioned?","qvi":"Bạn có muốn một bản sao bài báo tôi đề cập không?","opts":["No, I'm not.","Yes, I'd appreciate that.","A Thursday morning appointment."],"vi":["Không, tôi không.","Có, tôi đánh giá cao điều đó.","Một cuộc hẹn sáng thứ Năm."],"ans":"B","a":"E26-T05-26.mp3"},{"n":27,"q":"Did you decide on the design for the new logo?","qvi":"Bạn đã quyết định thiết kế cho logo mới chưa?","opts":["There are so many good options.","Please adjust that sign by the door.","Maybe he'll arrive today."],"vi":["Có quá nhiều lựa chọn tốt.","Làm ơn điều chỉnh biển báo bên cửa.","Có lẽ anh ấy sẽ đến hôm nay."],"ans":"A","a":"E26-T05-27.mp3"},{"n":28,"q":"Our bookstore is having a sale today, isn't it?","qvi":"Hiệu sách của chúng ta đang giảm giá hôm nay, phải không?","opts":["Sure, you can use my printer.","I really enjoyed that book.","It's only a small discount."],"vi":["Chắc chắn, bạn có thể dùng máy in của tôi.","Tôi thực sự thích cuốn sách đó.","Chỉ giảm giá nhỏ thôi."],"ans":"C","a":"E26-T05-28.mp3"},{"n":29,"q":"Why haven't the painters arrived yet?","qvi":"Tại sao thợ sơn chưa đến vậy?","opts":["The keys are in the desk drawer.","No, that's all right.","I heard that traffic is heavy this morning."],"vi":["Chìa khóa ở trong ngăn kéo bàn.","Không, không sao đâu.","Tôi nghe nói giao thông sáng nay đông đúc."],"ans":"C","a":"E26-T05-29.mp3"},{"n":30,"q":"Should I bring some flowers or some food to the party?","qvi":"i nên mang hoa hay thức ăn đến bữa tiệc?","opts":["He's right down the hall.","Don't you live next to a florist's shop?","A few more hours."],"vi":["Anh ấy ở ngay cuối hành lang.","Bạn không sống cạnh tiệm hoa sao?","Thêm vài giờ nữa."],"ans":"B","a":"E26-T05-30.mp3"},{"n":31,"q":"The meeting can wait until tomorrow.","qvi":"ộc họp có thể chờ đến ngày mai.","opts":["I'll make sure the room is set up.","Did you bring an umbrella?","No, he wasn't."],"vi":["Tôi sẽ đảm bảo phòng được chuẩn bị.","Bạn có mang ô không?","Không, anh ấy không phải."],"ans":"A","a":"E26-T05-31.mp3"}],"p3":[{"ns":[32,34],"script":[["W","Hello, Tariq. Could you do me a favor?","Chào Tariq. Bạn có thể giúp tôi một việc không?"],["M","Sure—what is it?","Chắc chắn rồi—việc gì vậy?"],["W","I'm meeting with the Gerhard Group at ten A.M. for the product pitch, and I need copies of your market analysis report made for each representative.","Tôi sẽ gặp nhóm Gerhard lúc 10 giờ sáng để trình bày sản phẩm, và tôi cần bản sao báo cáo phân tích thị trường của bạn cho từng đại diện."],["M","Aren't you at the office right now?","Bạn không đang ở văn phòng sao?"],["W","Actually, I came in early today, but I couldn't get the copy machine to work.","Thực ra, tôi đến sớm hôm nay, nhưng không thể làm máy photocopy hoạt động."],["M","Seriously? We bought it last month!","Thật sao? Chúng ta mua nó tháng trước mà!"],["W","I'm afraid so.","Tôi e là vậy."],["M","I just got off the train. I'll stop at Business Express on McAllister Street and take care of it on my way to the office.","Tôi vừa xuống tàu. Tôi sẽ ghé Business Express trên phố McAllister và xử lý việc đó trên đường đến văn phòng."]],"qs":[{"n":32,"q":"What does the woman ask the man to do for her?","qvi":"Người phụ nữ yêu cầu người đàn ông làm gì cho cô ấy?","opts":["Greet a client in the lobby","Present a product pitch","Organize some binders","Make some photocopies"],"vi":["Chào đón khách trong sảnh","Trình bày một bài giới thiệu sản phẩm","Sắp xếp một số bìa còng","Sao chép một số tài liệu"],"ans":"D"},{"n":33,"q":"What does the man say about some equipment?","qvi":"Người đàn ông nói gì về một số thiết bị?","opts":["It is operating smoothly.","It was purchased recently.","It needs to be plugged in.","It has not yet been updated."],"vi":["Nó đang hoạt động trơn tru.","Nó vừa được mua gần đây.","Nó cần được cắm điện.","Nó chưa được cập nhật."],"ans":"B"},{"n":34,"q":"Where is the man?","qvi":"Người đàn ông đang ở đâu?","opts":["At the office","At a train station","At a store","At a client’s headquarters"],"vi":["Tại văn phòng","Tại trạm tàu","Tại cửa hàng","Tại trụ sở của khách hàng"],"ans":"B"}],"a":"E26-T05-32-34.mp3"},{"ns":[35,37],"script":[["W","Delton Van Lines. How can I help you?","Delton Van Lines. Tôi có thể giúp gì cho bạn?"],["M","Hello. I'm the office manager at Woodsom Insurance Company. We are relocating to a new office in June and would like to book your services.","Chào. Tôi là quản lý văn phòng tại Công ty Bảo hiểm Woodsom. Chúng tôi sẽ chuyển đến văn phòng mới vào tháng Sáu và muốn đặt dịch vụ của bạn."],["W","Certainly! But before we reserve a date for the move, we'll need to come to your current location and estimate the cost of moving your furniture and equipment.","Chắc chắn rồi! Nhưng trước khi đặt ngày chuyển, chúng tôi cần đến vị trí hiện tại của bạn để ước tính chi phí di chuyển đồ nội thất và thiết bị."],["M","We have a staff meeting tomorrow morning, so no one's available to show you around then. But tomorrow afternoon works.","Chúng tôi có cuộc họp nhân viên sáng mai, nên không ai rảnh để hướng dẫn bạn lúc đó. Nhưng chiều mai thì được."],["W","Perfect! Our representative can be there at two. I'll just need to know where you're located.","Hoàn hảo! Đại diện của chúng tôi có thể đến lúc 2 giờ. Tôi chỉ cần biết vị trí của bạn."]],"qs":[{"n":35,"q":"Where does the woman most likely work?","qvi":"Người phụ nữ nhiều khả năng làm việc ở đâu?","opts":["At a furniture store","At a moving company","At a post office","At an office supply store"],"vi":["Tại cửa hàng đồ nội thất","Tại một công ty chuyển nhà","Tại bưu điện","Tại cửa hàng cung cấp văn phòng phẩm"],"ans":"B"},{"n":36,"q":"Why will a representative visit the man’s company tomorrow?","qvi":"Tại sao đại diện sẽ đến công ty của người đàn ông vào ngày mai?","opts":["To provide an estimate","To sign a contract","To give a presentation","To place an order"],"vi":["Để cung cấp báo giá","Để ký hợp đồng","Để trình bày","Để đặt một đơn hàng"],"ans":"A"},{"n":37,"q":"What information will the man most likely provide next?","qvi":"Người đàn ông nhiều khả năng sẽ cung cấp thông tin gì tiếp theo?","opts":["A company’s operating hours","An account number","A street address","A telephone number"],"vi":["Giờ làm việc của một công ty","Một số tài khoản","Một địa chỉ đường phố","Một số điện thoại"],"ans":"C"}],"a":"E26-T05-35-37.mp3"},{"ns":[38,40],"script":[["M","Doctor MacMillan, I'm calling from the human resources department. I'm in charge of your onboarding, and I wanted to confirm your start date. It's the first of April, right?","Bác sĩ MacMillan, tôi gọi từ bộ phận nhân sự. Tôi phụ trách việc onboarding của bạn, và tôi muốn xác nhận ngày bắt đầu. Là ngày 1 tháng Tư, đúng không?"],["W","Right. That's when I'll be joining the scientific research team. And as you probably know, I'm still finishing up a research paper with my current institution.","Đúng vậy. Đó là khi tôi sẽ tham gia đội ngũ nghiên cứu khoa học. Và như bạn có lẽ biết, tôi vẫn đang hoàn tất một bài nghiên cứu với tổ chức hiện tại."],["M","Yes, the director did tell me that. Your contract includes time for you to finish up your previous commitments. I can send it to you this afternoon.","Vâng, giám đốc đã kể cho tôi. Hợp đồng của bạn bao gồm thời gian để hoàn tất các cam kết trước đó. Tôi có thể gửi nó cho bạn chiều nay."]],"qs":[{"n":38,"q":"What department does the man work in?","qvi":"Người đàn ông làm việc ở phòng ban nào?","opts":["Legal","Accounting","Human resources","Public relations"],"vi":["Pháp lý","Kế toán","Nhân sự","Quan hệ công chúng"],"ans":"C"},{"n":39,"q":"What kind of work has the woman been hired to do?","qvi":"Người phụ nữ được thuê để làm loại công việc gì?","opts":["Scientific research","Book editing","Office management","Legal advising"],"vi":["Nghiên cứu khoa học","Biên tập sách","Quản lý văn phòng","Tư vấn pháp lý"],"ans":"A"},{"n":40,"q":"What will the man send the woman this afternoon?","qvi":"Chiều nay người đàn ông sẽ gửi gì cho người phụ nữ?","opts":["A password","A travel reimbursement","A security badge","A contract"],"vi":["Mật khẩu","Khoản hoàn trả chi phí đi lại","Thẻ an ninh","Hợp đồng"],"ans":"D"}],"a":"E26-T05-38-40.mp3"},{"ns":[41,43],"script":[["W1","We've been getting a lot of online orders for our chocolate candies lately. I'm glad to see the increase in orders, but I'm worried about meeting the demands. Are we going to be able to fill and ship all these orders?","Chúng ta gần đây nhận được nhiều đơn hàng trực tuyến cho kẹo sô cô la. Tôi vui vì thấy đơn hàng tăng, nhưng lo về việc đáp ứng nhu cầu. Chúng ta có thể hoàn tất và giao hết các đơn hàng này không?"],["M","I think we should hire a few more people to work in the mornings. They could help with packaging and shipping. What do you think, Rebecca?","Tôi nghĩ chúng ta nên thuê thêm vài người làm việc buổi sáng. Họ có thể giúp đóng gói và vận chuyển. Bạn nghĩ sao, Rebecca?"],["W2","I agree. I also think that we should ask if our delivery service can pick up our packages twice a day instead of just once a day—maybe every morning and afternoon. I'll call them today.","Tôi đồng ý. Tôi cũng nghĩ chúng ta nên hỏi dịch vụ giao hàng có thể lấy hàng hai lần một ngày thay vì chỉ một lần—có lẽ sáng và chiều. Tôi sẽ gọi họ hôm nay."]],"qs":[{"n":41,"q":"What recently happened at the business?","qvi":"Gần đây điều gì đã xảy ra tại doanh nghiệp?","opts":["Its monthly rent increased.","It received many orders.","It was featured in a magazine.","It passed an inspection."],"vi":["Tiền thuê hàng tháng tăng lên.","Nó nhận được nhiều đơn hàng mới","Nó được giới thiệu trên tạp chí","Nó vượt qua một cuộc kiểm tra"],"ans":"B"},{"n":42,"q":"According to the man, what will help the business?","qvi":"Theo người đàn ông, điều gì sẽ giúp ích cho doanh nghiệp?","opts":["Purchasing updated equipment","Offering different products","Extending store hours","Hiring more employees"],"vi":["Mua thiết bị cập nhật","Cung cấp các sản phẩm khác","Mở rộng giờ làm việc","Thuê thêm nhân viên"],"ans":"D"},{"n":43,"q":"Who does Rebecca say she will call today?","qvi":"Rebecca nói cô ấy sẽ gọi cho ai hôm nay?","opts":["A packaging designer","An Internet service provider","A delivery service","A bank"],"vi":["Một nhà thiết kế bao bì","Một nhà cung cấp dịch vụ Internet","Một dịch vụ giao hàng","Một ngân hàng"],"ans":"C"}],"a":"E26-T05-41-43.mp3"},{"ns":[44,46],"script":[["W","I spoke to the Mancini brothers. They just shipped our leather order—the hazelnut color. But it'll take a while to arrive. We don't have enough in stock to complete the ten sofa orders that we've received the past few days.","Tôi đã nói với anh em Mancini. Họ vừa gửi đơn hàng da của chúng ta—màu hạt dẻ. Nhưng sẽ mất thời gian để đến. Chúng ta không có đủ hàng tồn kho để hoàn tất mười đơn hàng sofa mà chúng ta nhận được vài ngày qua."],["M","What about the local leather supplier that brought us some samples last week? We could ask them whether they have enough for ten sofas.","Còn nhà cung cấp da địa phương mang mẫu cho chúng ta tuần trước thì sao? Chúng ta có thể hỏi họ xem có đủ cho mười sofa không."],["W","To be honest, I wasn't very impressed with the quality of their leather. I'd rather wait. I'll reach out to the customers about the delay.","Thật lòng, tôi không ấn tượng lắm với chất lượng da của họ. Tôi thà chờ. Tôi sẽ liên lạc với khách hàng về sự chậm trễ."]],"qs":[{"n":44,"q":"What do the speakers manufacture?","qvi":"Người nói sản xuất gì?","opts":["Shoes","Luggage","Furniture","Sports equipment"],"vi":["Giày","Hành lý","Đồ nội thất","Thiết bị thể thao"],"ans":"C"},{"n":45,"q":"Who does the man suggest contacting?","qvi":"Người đàn ông gợi ý liên hệ với ai?","opts":["A leather supplier","A delivery driver","An interior designer","A machine technician"],"vi":["Một nhà cung cấp da","Một tài xế giao hàng","Một nhà thiết kế nội thất","Một kỹ thuật viên máy móc"],"ans":"A"},{"n":46,"q":"Why is the woman opposed to making a change?","qvi":"Tại sao người phụ nữ phản đối việc thay đổi?","opts":["She has contracts with clients.","She is concerned about quality.","Overhead expenses will increase.","A license will expire soon."],"vi":["Cô ấy có hợp đồng với khách hàng","Cô ấy lo lắng về chất lượng","Chi phí vận hành sẽ tăng","Giấy phép sẽ sớm hết hạn"],"ans":"B"}],"a":"E26-T05-44-46.mp3"},{"ns":[47,49],"script":[["W","Thanks for coming in, Marcos. I just got the results from the consulting firm we hired. They have some ideas about how we can increase sales of our denim blue jeans.","Cảm ơn vì đã đến, Marcos. Tôi vừa nhận kết quả từ công ty tư vấn chúng ta thuê. Họ có một số ý tưởng về cách tăng doanh số quần jeans denim xanh."],["M","I hope so. What does our target audience want?","Tôi hy vọng vậy. Khán giả mục tiêu của chúng ta muốn gì?"],["W","Well, they think it's time we updated our brand with new styles or colors.","Ừ, họ nghĩ đã đến lúc cập nhật thương hiệu với kiểu dáng hoặc màu sắc mới."],["M","You know, it takes a lot of effort to develop and launch new styles.","Bạn biết đấy, cần nhiều nỗ lực để phát triển và ra mắt kiểu dáng mới."],["W","Yes. But, if we don't do it, another company will.","Vâng. Nhưng nếu chúng ta không làm, công ty khác sẽ làm."],["M","You're right. I'll ask Junko to come up with some new designs for us to consider.","Bạn đúng. Tôi sẽ yêu cầu Junko đưa ra một số thiết kế mới để chúng ta xem xét."]],"qs":[{"n":47,"q":"What are the speakers meeting to discuss?","qvi":"Người nói gặp nhau để thảo luận điều gì?","opts":["Safety regulations","Equipment upgrades","Budget cuts","Consultant recommendations"],"vi":["Quy định an toàn","Nâng cấp thiết bị","Cắt giảm ngân sách","Các khuyến nghị tư vấn"],"ans":"D"},{"n":48,"q":"What does the man mean when he says, “it takes a lot of effort to develop and launch new styles”?","qvi":"Người đàn ông có ý gì khi nói “phải mất rất nhiều nỗ lực để phát triển và tung ra những kiểu mới”?","opts":["He is excited about a challenge.","He is surprised at a competitor’s choices.","He is doubtful about a suggestion.","He thinks more employees should be hired."],"vi":["Anh ấy hào hứng với một thử thách","Anh ấy ngạc nhiên về lựa chọn của đối thủ","Anh ấy nghi ngờ về một đề xuất","Anh ấy nghĩ nên thuê thêm nhân viên"],"ans":"C"},{"n":49,"q":"Who most likely is Junko?","qvi":"Junko nhiều khả năng là ai?","opts":["A focus group leader","A clothing designer","A sales associate","An accountant"],"vi":["Người điều hành nhóm thảo luận","Nhà thiết kế quần áo","Người bán hàng","Kế toán"],"ans":"B"}],"a":"E26-T05-47-49.mp3"},{"ns":[50,52],"script":[["M","Hi, Gabriela. Thanks for agreeing to give me the highlights of the budget discussion from the monthly meeting. I'm back from vacation and still catching up.","Chào Gabriela. Cảm ơn vì đã đồng ý cập nhật cho tôi những điểm chính về cuộc thảo luận ngân sách trong cuộc họp hàng tháng. Tôi vừa về từ kỳ nghỉ và vẫn đang bắt kịp công việc."],["W","Sure. Here's a copy of the report. Everyone on the board of Tennis United agreed to the fee increase for the tennis camp for young players.","Không có gì. Đây là bản sao báo cáo. Mọi người trong hội đồng quản trị của Tennis United đều đồng ý tăng phí cho trại tennis dành cho các vận động viên trẻ."],["M","Good. And why do we have T-shirts listed as an expense item?","Tốt rồi. Và tại sao chúng ta lại có áo thun trong hạng mục chi phí?"],["W","Although the next tournament's in the fall, the T-shirts were ordered very early. That way we received half off the price, since the supplier wanted to get rid of his summer inventory.","Mặc dù giải đấu tiếp theo diễn ra vào mùa thu, nhưng áo thun đã được đặt hàng rất sớm. Nhờ vậy chúng ta được giảm nửa giá, vì nhà cung cấp muốn thanh lý hàng tồn kho mùa hè."]],"qs":[{"n":50,"q":"Why did the man miss a meeting?","qvi":"Tại sao người đàn ông bỏ lỡ một cuộc họp?","opts":["He was stuck in traffic.","He had a medical appointment.","He was speaking with a client.","He was away on vacation."],"vi":["Anh ấy mắc kẹt trong giao thông","Anh ấy có cuộc hẹn y tế","Anh ấy đang nói chuyện với khách hàng","Anh ấy đang đi nghỉ"],"ans":"D"},{"n":51,"q":"Which sport does the speakers’ organization promote?","qvi":"Tổ chức của người nói quảng bá môn thể thao nào?","opts":["Tennis","Volleyball","Swimming","Gymnastics"],"vi":["Quần vợt","Bóng chuyền","Bơi lội","Thể dục dụng cụ"],"ans":"A"},{"n":52,"q":"Why were T-shirts ordered early?","qvi":"Tại sao áo phông được đặt hàng sớm?","opts":["To avoid potential delays","To get free delivery","To receive a discount","To meet heavy demand"],"vi":["Để tránh trì hoãn tiềm năng","Để được giao hàng miễn phí","Để nhận được chiết khấu","Để đáp ứng nhu cầu cao"],"ans":"C"}],"a":"E26-T05-50-52.mp3"},{"ns":[53,55],"script":[["W","The first item on today's meeting agenda is our bid to renovate the Morrisville Bridge. Do we have an update on that yet?","Mục đầu tiên trong nghị sự họp hôm nay là đề xuất của chúng ta về việc cải tạo cầu Morrisville. Chúng ta có cập nhật gì về việc đó chưa?"],["M1","Yes—unfortunately we didn't get the contract.","Vâng—thật tiếc là chúng ta không trúng thầu."],["M2","Yes, the only explanation given was that another construction company submitted a proposal with a shorter timeline.","Vâng, lý do duy nhất được đưa ra là một công ty xây dựng khác đã nộp đề xuất với thời gian ngắn hơn."],["W","So, what do we know about this competitor? Have they worked on other local projects?","Vậy chúng ta biết gì về đối thủ này? Họ có tham gia các dự án địa phương khác không?"],["M1","The only thing I heard was their name—CDQ Construction Company.","Điều duy nhất tôi nghe được là tên của họ—Công ty Xây dựng CDQ."],["W","Well, I'd like to know more about them. Can you two do some research before our next meeting?","Ừm, tôi muốn biết thêm về họ. Hai anh có thể nghiên cứu trước cuộc họp tiếp theo không?"]],"qs":[{"n":53,"q":"What industry do the speakers most likely work in?","qvi":"Người nói có khả năng làm việc trong ngành nào?","opts":["Energy","Finance","Construction","Manufacturing"],"vi":["Năng lượng","Tài chính","Xây dựng","Sản xuất"],"ans":"C"},{"n":54,"q":"What is the reason a company did not get a contract?","qvi":"Lý do công ty không nhận được hợp đồng là gì?","opts":["Some costs were too high.","A facility failed an inspection.","Some paperwork was submitted late.","A competitor can complete a project faster."],"vi":["Một số chi phí quá cao","Một cơ sở không vượt qua kiểm tra","Một số giấy tờ nộp muộn","Đối thủ cạnh tranh có thể hoàn thành dự án nhanh hơn"],"ans":"D"},{"n":55,"q":"What does the woman ask the men to do?","qvi":"Người phụ nữ yêu cầu những người đàn ông làm gì?","opts":["Visit a facility","Conduct some research","Rewrite a proposal","Contact some vendors"],"vi":["Tham quan một cơ sở","Thực hiện một số nghiên cứu","Viết lại một đề xuất","Liên hệ một số nhà cung cấp"],"ans":"B"}],"a":"E26-T05-53-55.mp3"},{"ns":[56,58],"script":[["W","Did you see that the results of last month's employee survey have been compiled? All the staff feedback is available.","Anh có thấy kết quả khảo sát nhân viên tháng trước đã được tổng hợp chưa? Tất cả phản hồi từ nhân viên đều sẵn sàng."],["M","Yes, and I just finished reviewing the comments.","Vâng, và tôi vừa xem xong các bình luận."],["W","You know, I noticed one recurring complaint. The size of the break room is too small. Perhaps we could enlarge the break room by having the wall taken down between it and the meeting room next door.","Anh biết đấy, tôi nhận thấy một khiếu nại lặp lại nhiều lần. Kích thước phòng nghỉ quá nhỏ. Có lẽ chúng ta có thể mở rộng phòng nghỉ bằng cách phá bỏ bức tường giữa nó và phòng họp bên cạnh."],["M","Well, we do have money available in the budget.","Ừm, chúng ta vẫn còn tiền trong ngân sách."],["W","Then could you reach out to your contact at the construction company?","Vậy anh có thể liên hệ với người quen ở công ty xây dựng không?"],["M","I can't do it this afternoon, since I need to see a dentist, but I will definitely make the call.","Tôi không thể làm chiều nay vì phải gặp nha sĩ, nhưng tôi chắc chắn sẽ gọi."]],"qs":[{"n":56,"q":"What did the company do last month?","qvi":"Tháng trước công ty đã làm gì?","opts":["It opened a second location.","It merged with another business.","It launched a new product.","It conducted an employee survey."],"vi":["Mở địa điểm thứ hai","Hợp nhất với doanh nghiệp khác","Ra mắt sản phẩm mới","Tiến hành khảo sát nhân viên"],"ans":"D"},{"n":57,"q":"Why does the man say, “we do have money available in the budget”?","qvi":"Tại sao người đàn ông nói “chúng ta vẫn có tiền trong ngân sách”?","opts":["To request another budget analysis","To suggest hiring additional employees","To agree with a proposed renovation","To recommend an increase in advertising"],"vi":["Để yêu cầu một bản phân tích ngân sách khác","Để đề xuất thuê thêm nhân viên","Để đồng ý với việc cải tạo được đề xuất","Để khuyến nghị tăng quảng cáo"],"ans":"C"},{"n":58,"q":"What does the man say he has to do this afternoon?","qvi":"Người đàn ông nói anh ấy phải làm gì chiều nay?","opts":["Have his car repaired","Give a presentation","Go to a dentist appointment","Attend a reception"],"vi":["Sửa xe","Thuyết trình","Đến gặp nha sĩ","Dự tiệc chiêu đãi"],"ans":"C"}],"a":"E26-T05-56-58.mp3"},{"ns":[59,61],"script":[["W","Thanks for calling Hang's Metal Recycling Company. How can I help you?","Cảm ơn đã gọi đến Công ty Tái chế Kim loại Hang. Tôi có thể giúp gì cho anh?"],["M","Hi. I'm with Shannak Construction Company. We've got a lot of brass metal scrap from a recent remodeling job. Are you currently buying metal scrap?","Chào. Tôi từ Công ty Xây dựng Shannak. Chúng tôi có nhiều phế liệu kim loại đồng từ công việc sửa chữa cải tạo gần đây. Công ty có đang mua phế liệu kim loại không?"],["W","Yes, we are. We currently pay two dollars a pound.","Vâng, chúng tôi đang mua. Hiện tại chúng tôi trả hai đô la một pound."],["M","Oh, there's another recycling center that pays two dollars and twenty-five cents a pound. Would you be willing to match their price?","Ồ, có một trung tâm tái chế khác trả hai đô la hai mươi lăm cent một pound. Công ty có sẵn lòng khớp giá đó không?"],["W","Yes, we have a price-match guarantee.","Vâng, chúng tôi có chính sách khớp giá."],["M","Great. I'll bring the metal to you this afternoon, then.","Tuyệt vời. Vậy tôi sẽ mang kim loại đến chiều nay."]],"qs":[{"n":59,"q":"Where does the woman work?","qvi":"Người phụ nữ làm việc ở đâu?","opts":["At a recycling company","At an appliance store","At a manufacturing company","At an architectural firm"],"vi":["Tại một công ty tái chế","Tại cửa hàng thiết bị","Tại công ty sản xuất","Tại công ty kiến trúc"],"ans":"A"},{"n":60,"q":"What does the man ask the woman to do?","qvi":"Người đàn ông yêu cầu người phụ nữ làm gì?","opts":["Revise a contract","Match a competitor’s offer","Refund a delivery fee","Sign in at a security desk"],"vi":["Sửa hợp đồng","Bằng với mức giá đề nghị của đối thủ","Hoàn tiền phí giao hàng","Đăng ký tại quầy an ninh"],"ans":"B"},{"n":61,"q":"What does the man say he will do this afternoon?","qvi":"Chiều nay người đàn ông sẽ làm gì?","opts":["Conduct an inspection","Sign a document","Deliver some materials","Update a Web site"],"vi":["Tiến hành kiểm tra","Ký tài liệu","Giao một số vật liệu","Cập nhật trang web"],"ans":"C"}],"a":"E26-T05-59-61.mp3"},{"ns":[62,64],"script":[["W","Hi, I just got off the phone with management. They're not happy. The construction of the train tunnel isn't progressing fast enough.","Chào, tôi vừa kết thúc cuộc gọi với ban quản lý. Họ không hài lòng. Việc xây dựng đường hầm tàu hỏa không tiến triển đủ nhanh."],["M","Yeah, I'm not surprised. The drilling is done now. The thing is, we can't start installing the support columns until we have all the materials for the concrete.","Ừ, tôi không ngạc nhiên. Việc khoan đã hoàn tất. Vấn đề là chúng ta không thể bắt đầu lắp đặt cột chống đỡ cho đến khi có đầy đủ vật liệu cho bê tông."],["W","When are the materials going to get here?","Vật liệu sẽ đến khi nào?"],["M","A week, maybe two.","Một tuần, có lẽ hai tuần."],["W","Let's see if the shipment can be expedited. Can you do that?","Hãy xem liệu lô hàng có thể được đẩy nhanh không. Anh có thể làm điều đó không?"],["M","Sure. I'll call the supplier to ask about getting it here sooner.","Chắc chắn. Tôi sẽ gọi nhà cung cấp để hỏi về việc giao sớm hơn."],["W","In the meantime, I'm going to write an e-mail to management to explain how we're attempting to resolve the situation.","Trong lúc đó, tôi sẽ viết email cho ban quản lý để giải thích cách chúng ta đang cố gắng giải quyết tình hình."]],"qs":[{"n":62,"q":"Look at the graphic. Which project phase was just completed?","qvi":"Nhìn vào hình. Giai đoạn nào của dự án vừa được hoàn thành?","opts":["Phase 1","Phase 2","Phase 3","Phase 4"],"vi":["Giai đoạn 1","Giai đoạn 2","Giai đoạn 3","Giai đoạn 4"],"ans":"B"},{"n":63,"q":"What does the woman ask the man to do?","qvi":"Người phụ nữ yêu cầu người đàn ông làm gì?","opts":["Request an earlier delivery date","Consult with a safety inspector","Post some construction plans","Forward an invoice"],"vi":["Yêu cầu giao hàng sớm hơn","Tham khảo ý kiến của thanh tra an toàn","Đăng tải một số bản vẽ xây dựng","Gửi hóa đơn"],"ans":"A"},{"n":64,"q":"What does the woman intend to do next?","qvi":"Người phụ nữ dự định làm gì tiếp theo?","opts":["Review some data","Move a vehicle","Increase the size of a crew","Contact the management team"],"vi":["Xem xét một số dữ liệu","Di chuyển một phương tiện","Tăng số lượng nhân công","Liên hệ với đội ngũ quản lý"],"ans":"D"}],"a":"E26-T05-62-64.mp3","img":"g62.png"},{"ns":[65,67],"script":[["M","The city just posted its new parking rates, and we need to talk about how they'll affect our restaurant's food delivery service. I'm worried we'll lose money because we'll need to pay more for parking while the delivery driver takes the food to customers.","Thành phố vừa công bố mức phí đỗ xe mới, và chúng ta cần thảo luận về cách chúng ảnh hưởng đến dịch vụ giao đồ ăn của nhà hàng. Tôi lo chúng ta sẽ lỗ vì phải trả thêm phí đỗ xe trong lúc tài xế giao thức ăn cho khách."],["W","Wow. Parking in our main delivery area is up to fifteen dollars an hour? That is a problem. But offering free delivery attracts a lot of business. What else can we do to lower expenses?","Ồ. Phí đỗ xe ở khu vực giao hàng chính lên đến mười lăm đô la một giờ cơ à? Đó là vấn đề lớn. Nhưng cung cấp giao hàng miễn phí sẽ thu hút nhiều khách hàng. Chúng ta có thể làm gì khác để giảm chi phí không?"],["M","We could start using bicycle delivery whenever possible. That should help.","Chúng ta có thể bắt đầu sử dụng giao hàng bằng xe đạp khi có thể. Điều đó sẽ giúp ích."],["W","Good idea. I'll talk to our drivers to see who's willing to switch to bicycle deliveries for customers nearby. Some people really like the exercise.","Ý hay đấy. Tôi sẽ nói chuyện với các tài xế để xem ai sẵn lòng chuyển sang giao bằng xe đạp cho khách ở gần đây không. Một số người thực sự thích tập luyện mà."]],"qs":[{"n":65,"q":"What type of business do the speakers work for?","qvi":"Loại hình kinh doanh của người nói là gì?","opts":["A restaurant","A law firm","An office-supply store","A flower shop"],"vi":["Nhà hàng","Công ty luật","Cửa hàng cung cấp văn phòng phẩm","Cửa hàng hoa"],"ans":"A"},{"n":66,"q":"Look at the graphic. In which area of the city does the business make most of its deliveries?","qvi":"Nhìn vào hình. Doanh nghiệp thực hiện phần lớn các chuyến giao hàng ở khu vực nào của thành phố?","opts":["The waterfront district","The historic district","The residential district","The downtown district"],"vi":["Khu ven hồ","Khu vực lịch sử","Khu dân cư","Khu trung tâm"],"ans":"D"},{"n":67,"q":"How does the man propose lowering business expenses?","qvi":"Người đàn ông đề xuất giảm chi phí kinh doanh bằng cách nào?","opts":["By reducing packaging waste","By introducing bicycle delivery","By switching to a new supplier","By moving to a smaller building"],"vi":["Giảm rác bao bì","Giới thiệu dịch vụ giao hàng bằng xe đạp","Chuyển sang nhà cung cấp mới","Chuyển đến tòa nhà nhỏ hơn"],"ans":"B"}],"a":"E26-T05-65-67.mp3","img":"g65.png"},{"ns":[68,70],"script":[["M","When customers walk into Southern Regional Bank, I want them to feel confident about entrusting their money to us. As I mentioned the last time we met, I'm hoping your interior design firm can give our lobby a more polished, professional look.","Khi khách hàng bước vào Ngân hàng Khu vực Miền Nam, tôi muốn họ cảm thấy tự tin khi giao phó tiền bạc cho chúng tôi. Như tôi đã đề cập lần gặp trước, tôi hy vọng công ty thiết kế nội thất của quý vị có thể mang lại vẻ ngoài chuyên nghiệp, bóng bẩy hơn cho sảnh của chúng tôi."],["W","Our proposal does just that. Here—take a look. The cover page includes a summary of the renovations.","Đề xuất của chúng tôi làm chính xác điều đó. Đây—hãy xem qua. Trang bìa bao gồm tóm tắt các công việc cho lần cải tạo này."],["M","Hmm. Do you really think we need skylights? That would be a big expense.","Ừm. Bên cô có thực sự nghĩ chúng ta cần giếng trời không? Đó sẽ là chi phí lớn."],["W","There aren't many windows in your lobby, so it's the best way to bring more natural light into the room. Besides, our proposed renovations would actually come in under budget. If you turn to page four, you'll see the cost breakdown.","Sảnh của các anh không có nhiều cửa sổ, nên đó là cách tốt nhất để đưa thêm ánh sáng tự nhiên vào phòng. Hơn nữa, các công việc cải tạo đề xuất của chúng tôi thực tế sẽ dưới ngân sách. Nếu anh lật sang trang bốn, anh sẽ thấy phân tích chi phí cụ thể."]],"qs":[{"n":68,"q":"Who most likely is the woman?","qvi":"Người phụ nữ nhiều khả năng là ai?","opts":["A hotel manager","An interior designer","A construction worker","A real estate agent"],"vi":["Quản lý khách sạn","Nhà thiết kế nội thất","Công nhân xây dựng","Nhân viên môi giới bất động sản"],"ans":"B"},{"n":69,"q":"Look at the graphic. Which step does the man ask about?","qvi":"Nhìn vào hình. Người đàn ông hỏi về bước nào?","opts":["Step 1","Step 2","Step 3","Step 4"],"vi":["Bước 1","Bước 2","Bước 3","Bước 4"],"ans":"A"},{"n":70,"q":"What will the man most likely do next?","qvi":"Người đàn ông có thể làm gì tiếp theo?","opts":["Send a contract","Go to the lobby","Look at some photographs","Review a cost estimate"],"vi":["Gửi hợp đồng","Đi ra sảnh","Xem một số ảnh","Xem lại bảng chi phí"],"ans":"D"}],"a":"E26-T05-68-70.mp3","img":"g68.png"}],"p4":[{"ns":[71,73],"script":[["W","Welcome to the monthly company staff meeting. Before I begin my report on last month's sales figures, I want to congratulate our fantastic IT team! The sales tracking system they built allows us to easily share results with colleagues from other branches. All employees are required to attend a training session on how to use it. A registration link will be sent out this afternoon. Now, let's look at last month's figures. We need to decide if we're ready to expand into more markets.","Chào mừng đến với cuộc họp nhân viên hàng tháng của công ty. Trước khi bắt đầu báo cáo về số liệu bán hàng tháng trước, tôi muốn chúc mừng đội ngũ IT tuyệt vời của chúng ta! Hệ thống theo dõi bán hàng mà họ xây dựng cho phép chúng ta dễ dàng chia sẻ kết quả với đồng nghiệp từ các chi nhánh khác. Tất cả nhân viên phải tham gia buổi đào tạo về cách sử dụng hệ thống. Liên kết đăng ký sẽ được gửi vào chiều nay. Bây giờ, hãy xem số liệu tháng trước. Chúng ta cần quyết định xem liệu đã sẵn sàng mở rộng sang nhiều thị trường hơn chưa."]],"qs":[{"n":71,"q":"Who most likely is the speaker?","qvi":"Người nói có khả năng là ai?","opts":["A department manager","A news reporter","A marketing consultant","A computer programmer"],"vi":["Quản lý bộ phận","Phóng viên","Cố vấn marketing","Lập trình viên máy tính"],"ans":"A"},{"n":72,"q":"Why does the speaker congratulate a team?","qvi":"Tại sao người nói chúc mừng một nhóm?","opts":["For keeping expenses low","For creating a useful tool","For meeting a tight deadline","For achieving the most sales"],"vi":["Giữ chi phí thấp","Tạo ra một công cụ hữu ích","Hoàn thành hạn chót gấp","Đạt doanh số cao nhất"],"ans":"B"},{"n":73,"q":"What are the listeners required to do?","qvi":"Người nghe được yêu cầu làm gì?","opts":["Register for some training","Review a floor plan","Participate in a mentoring program","Provide copies of certifications"],"vi":["Đăng ký một khóa đào tạo","Xem lại sơ đồ mặt bằng","Tham gia chương trình cố vấn","Nộp bản sao chứng chỉ"],"ans":"A"}],"a":"E26-T05-71-73.mp3"},{"ns":[74,76],"script":[["M","Hello. You've reached the communications team of Business As Usual, the talk show about starting a new business. If you are calling because you'd like to appear on our show, we'd love to hear your story! To record your story idea, please press one. Please note: it is necessary to keep your message under 60 seconds. Submissions that are more than a minute long will not be reviewed. The typical timeline for the review process is two weeks, with longer wait times expected around holidays.","Xin chào. Bạn đã liên lạc với đội ngũ truyền thông của Business As Usual, chương trình talk show về khởi nghiệp. Nếu bạn gọi vì muốn xuất hiện trên chương trình, chúng tôi rất mong nghe câu chuyện của bạn! Để ghi âm ý tưởng câu chuyện, vui lòng nhấn phím một. Lưu ý: cần giữ thông điệp dưới 60 giây. Các bản ghi vượt quá một phút sẽ không được xem xét. Thời gian đánh giá thông thường là hai tuần, với thời gian chờ đợi lâu hơn dự kiến quanh các kỳ nghỉ lễ."]],"qs":[{"n":74,"q":"What are the listeners invited to do?","qvi":"Người nghe được mời làm gì?","opts":["Download a calendar","Reserve tickets","Submit a picture","Share a story"],"vi":["Tải lịch","Đặt vé","Gửi ảnh","Chia sẻ câu chuyện"],"ans":"D"},{"n":75,"q":"What guideline does the speaker emphasize?","qvi":"Quy định nào người nói nhấn mạnh?","opts":["Recordings must be kept short.","Electronic devices must be turned off.","Professional references must be provided.","Vehicles must be parked in a designated area."],"vi":["Bản ghi phải ngắn","Thiết bị điện tử phải tắt","Phải nộp thư giới thiệu","Xe phải đỗ đúng khu vực"],"ans":"A"},{"n":76,"q":"According to the speaker, what may cause a delay?","qvi":"Điều gì có thể gây chậm trễ?","opts":["Bad weather","Holidays","A construction project","Staff changes"],"vi":["Thời tiết xấu","Các kỳ nghỉ lễ","Công trình xây dựng","Thay đổi nhân sự"],"ans":"B"}],"a":"E26-T05-74-76.mp3"},{"ns":[77,79],"script":[["W","Welcome to the culinary tour of downtown Springfield. Today, you'll taste a variety of local foods. Normally I'd start by taking you inside Zelda's Bakery to try one of their famous corn muffins, but we have such a large group today. Instead, we're going to head directly to the open-air market. There you'll find a wide selection of the homemade breads, jams, and pastries that we're noted for. After that, we'll head to the original Springfield cornmill, which is still in use today. And remember to keep your tour ticket. It's good for one free entry at the local museum.","Chào mừng đến với tour ẩm thực tại trung tâm Springfield. Hôm nay, quý vị sẽ nếm thử nhiều món ăn địa phương đa dạng. Thường thì tôi sẽ bắt đầu bằng việc dẫn quý vị vào Zelda's Bakery để thử một trong những chiếc muffin ngô nổi tiếng, nhưng hôm nay nhóm chúng ta khá đông. Thay vào đó, chúng ta sẽ đi thẳng đến chợ trời. Ở đó, quý vị sẽ tìm thấy nhiều lựa chọn bánh mì tự làm, mứt và bánh ngọt mà chúng ta nổi tiếng. Sau đó, chúng ta sẽ đến nhà máy xay ngô Springfield nguyên bản, vẫn còn hoạt động đến nay. Và nhớ giữ vé tour nhé. Nó có giá trị cho một lần vào cửa miễn phí tại bảo tàng địa phương."]],"qs":[{"n":77,"q":"What is the focus of a tour?","qvi":"Chuyến tham quan tập trung vào chủ đề gì?","opts":["Food","Architecture","Nature","Art"],"vi":["Ẩm thực","Kiến trúc","Thiên nhiên","Nghệ thuật"],"ans":"A"},{"n":78,"q":"What does the speaker imply when she says, “we have such a large group today”?","qvi":"Khi nói “chúng ta có một nhóm rất đông hôm nay”, người nói muốn ám chỉ điều gì?","opts":["She is happy about the popularity of a tour.","She will need to use a microphone.","An additional tour guide is needed.","A shop is not big enough for everyone."],"vi":["Bà ấy vui vì tour rất đông","Bà ấy cần dùng micro","Cần thêm hướng dẫn viên","Cửa hàng quá nhỏ cho tất cả mọi người"],"ans":"D"},{"n":79,"q":"What will a ticket allow the listeners to do?","qvi":"Vé sẽ cho phép người nghe làm gì?","opts":["Attend a performance","Visit a museum","Participate in a class","Enter a contest"],"vi":["Xem biểu diễn","Tham quan bảo tàng","Tham gia lớp học","Tham gia cuộc thi"],"ans":"B"}],"a":"E26-T05-77-79.mp3"},{"ns":[80,82],"script":[["W","The Novikov Award is named after Maksim Novikov, the founder of Novikov Aviation. It is given each year to a company that has made outstanding contributions to the aviation industry. The company chosen for the award this year was frustrated by the lack of qualified job applicants and decided to do something about it. Zenith Aviation's apprenticeship program has trained hundreds of workers for careers in aircraft maintenance and repair. Dozens of firms nationwide have copied the program. Before I present the award, please direct your attention to the screen for a video highlighting the program's effectiveness.","Giải thưởng Novikov được đặt theo tên Maksim Novikov, người sáng lập Novikov Aviation. Nó được trao hàng năm cho một công ty có đóng góp xuất sắc cho ngành hàng không. Công ty được chọn cho giải thưởng năm nay từng thất vọng vì thiếu ứng viên đủ điều kiện và quyết định làm gì đó. Chương trình học việc của Zenith Aviation đã đào tạo hàng trăm công nhân cho sự nghiệp bảo dưỡng và sửa chữa máy bay. Hàng chục công ty trên toàn quốc đã sao chép chương trình. Trước khi trao giải, vui lòng hướng sự chú ý đến màn hình để xem video nhấn mạnh hiệu quả của chương trình."]],"qs":[{"n":80,"q":"What industry was the Novikov Award created for?","qvi":"Giải thưởng Novikov dành cho ngành nào?","opts":["Aviation","Chemical engineering","Medical research","Television production"],"vi":["Hàng không","Kỹ thuật hóa học","Nghiên cứu y học","Sản xuất truyền hình"],"ans":"A"},{"n":81,"q":"Why was this year’s award recipient selected?","qvi":"Tại sao người nhận giải năm nay được chọn?","opts":["For launching a unique advertising campaign","For developing a successful training program","For maintaining a perfect safety record","For making a scientific discovery"],"vi":["Khởi động chiến dịch quảng cáo độc đáo","Phát triển chương trình đào tạo thành công","Duy trì hồ sơ an toàn hoàn hảo","Khám phá khoa học"],"ans":"B"},{"n":82,"q":"What does the speaker ask the listeners to do?","qvi":"Người nói yêu cầu người nghe làm gì?","opts":["Get ready to watch a video","Applaud the winner","Share copies of a handout","Read a set of directions"],"vi":["Sẵn sàng xem video","Vỗ tay cho người thắng giải","Chia sẻ bản phát tay","Đọc hướng dẫn"],"ans":"A"}],"a":"E26-T05-80-82.mp3"},{"ns":[83,85],"script":[["M","Thank you for allowing me the opportunity to speak at this city council meeting. On behalf of the transportation department, I'd like to present a proposal to fund the replacement of all 350 bus-stop shelters in our city. We feel this is a worthwhile investment because the current shelters aren't in good shape. Many of them have cracked glass and broken benches. We want to go with Urban Retreat because its shelters are made of durable materials. While less expensive options are available, its models include a display for advertisements. These shelters could provide the city with a new source of income.","Cảm ơn vì đã cho tôi cơ hội phát biểu tại cuộc họp hội đồng thành phố này. Thay mặt sở giao thông, tôi xin trình bày đề xuất tài trợ thay thế toàn bộ 350 mái che trạm xe buýt trong thành phố. Chúng tôi tin đây là khoản đầu tư đáng giá vì các mái che hiện tại không còn tốt. Nhiều cái có kính nứt và ghế ngồi hỏng. Chúng tôi muốn chọn Urban Retreat vì mái che của họ làm từ vật liệu bền. Mặc dù có lựa chọn rẻ hơn, nhưng mẫu của họ bao gồm màn hình quảng cáo. Những mái che này có thể mang lại nguồn thu mới cho thành phố."]],"qs":[{"n":83,"q":"Who is the speaker presenting to?","qvi":"Người nói đang trình bày với ai?","opts":["Loan officers","Construction workers","City council members","Bus drivers"],"vi":["Nhân viên tín dụng","Công nhân xây dựng","Hội đồng thành phố","Tài xế xe buýt"],"ans":"C"},{"n":84,"q":"What does the speaker say about some existing structures?","qvi":"Người nói nói gì về một số cấu trúc hiện có?","opts":["They are in disrepair.","They are very small.","They were not assembled correctly.","They were installed last year."],"vi":["Chúng đang xuống cấp","Chúng quá nhỏ","Lắp ráp sai","Lắp đặt năm ngoái"],"ans":"A"},{"n":85,"q":"Why does the speaker say, “its models include a display for advertisements”?","qvi":"Tại sao người nói nói “mẫu này có chỗ cho quảng cáo”?","opts":["To respond to a request for information","To justify a cost","To express surprise","To suggest adding to a product line"],"vi":["Để trả lời yêu cầu thông tin","Để biện minh chi phí","Để thể hiện sự ngạc nhiên","Gợi ý thêm sản phẩm mới"],"ans":"B"}],"a":"E26-T05-83-85.mp3"},{"ns":[86,88],"script":[["W","Hi. It's Sarai. I'm calling about the new wallpaper patterns that your team submitted. We all really like the geometric prints. I'm almost certain that all of those will be approved for production in several different color schemes. And the wallpaper patterns for children's rooms are all so imaginative. You have some truly creative people on your design team. However, the animal-themed prints you sent—the thing is, we have a full supply of those in stock. Call me back so we can discuss it.","Chào. Tôi là Sarai. Tôi gọi về các mẫu giấy dán tường mới mà đội ngũ của bạn gửi. Chúng tôi đều rất thích các họa tiết hình học. Tôi gần như chắc chắn rằng tất cả sẽ được phê duyệt sản xuất với nhiều bảng màu khác nhau. Và các mẫu giấy dán tường cho phòng trẻ em đều rất sáng tạo. Đội ngũ thiết kế của bạn có những người thực sự sáng tạo. Tuy nhiên, các họa tiết chủ đề động vật mà bạn gửi—vấn đề là chúng tôi có đầy hàng tồn kho cho loại đó. Gọi lại cho tôi để thảo luận nhé."]],"qs":[{"n":86,"q":"What does the speaker’s company sell?","qvi":"Công ty của người nói bán gì?","opts":["Clothing","Flowers","Toys","Wallpaper"],"vi":["Quần áo","Hoa","Đồ chơi","Giấy dán tường"],"ans":"D"},{"n":87,"q":"Why does the speaker praise the listener’s team?","qvi":"Tại sao người nói khen nhóm người nghe?","opts":["They stayed under budget.","They won an award.","They showed creativity.","They completed some work on schedule."],"vi":["Hoàn thành dưới ngân sách","Thắng giải thưởng","Thể hiện sự sáng tạo","Hoàn thành công việc đúng tiến độ"],"ans":"C"},{"n":88,"q":"Why does the speaker say, “we have a full supply of those in stock”?","qvi":"Tại sao người nói nói “chúng tôi có đầy đủ hàng trong kho”?","opts":["To report that inventory has been completed","To offer to share some supplies with another store","To explain that some designs are not needed","To confirm that a customer’s order can be filled"],"vi":["Báo cáo kiểm kho đã hoàn tất","Gợi ý chia sẻ hàng với cửa hàng khác","Giải thích không cần một số mẫu","Xác nhận đơn hàng có thể hoàn tất"],"ans":"C"}],"a":"E26-T05-86-88.mp3"},{"ns":[89,91],"script":[["M","In local news, the opening of the Stewart Performing Arts Center tomorrow night has attracted widespread attention. This state-of-the-art center holds three different theaters. The designer won an award for the building's insulated walls. They have rubber material that absorbs sound from the other theaters and nearby trains. On top of this, the interior decoration is magnificent. If you'd like to see some photos, browse upcoming shows, and plan your visit, go to the theater's Web site. We warn you, though—many shows are already sold out!","Trong tin địa phương, lễ khai trương Trung tâm Nghệ thuật Biểu diễn Stewart vào tối mai đã thu hút sự chú ý rộng rãi. Trung tâm hiện đại này có ba nhà hát khác nhau. Nhà thiết kế đã thắng giải cho các bức tường cách âm của tòa nhà. Chúng có vật liệu cao su hấp thụ âm thanh từ các nhà hát khác và tàu hỏa gần đó. Hơn nữa, trang trí nội thất rất lộng lẫy. Nếu bạn muốn xem ảnh, duyệt các buổi biểu diễn sắp tới và lập kế hoạch thăm quan, hãy truy cập website của nhà hát. Chúng tôi cảnh báo trước—nhiều buổi biểu diễn đã bán hết vé!"]],"qs":[{"n":89,"q":"According to the speaker, what will be opening soon?","qvi":"Theo người nói, cái gì sắp mở cửa?","opts":["A restaurant","A sports arena","A performing arts center","A train station"],"vi":["Nhà hàng","Sân vận động","Trung tâm nghệ thuật biểu diễn","Ga tàu"],"ans":"C"},{"n":90,"q":"Why did the building’s designer win an award?","qvi":"Tại sao nhà thiết kế tòa nhà nhận giải?","opts":["For using solar power","For creating a rooftop garden","For installing a moving light display","For employing sound-absorbing walls"],"vi":["Dùng năng lượng mặt trời","Tạo vườn trên mái","Lắp đặt hệ thống đèn di chuyển","Dùng tường cách âm"],"ans":"D"},{"n":91,"q":"What does the speaker emphasize about upcoming events?","qvi":"Người nói nhấn mạnh điều gì về sự kiện sắp tới?","opts":["Many of them are sold out.","Some of them will be affected by the weather.","Public transportation will be free.","Discounts are available for large groups."],"vi":["Nhiều sự kiện đã bán hết","Một số bị ảnh hưởng bởi thời tiết","Giao thông công cộng miễn phí","Có giảm giá cho nhóm lớn"],"ans":"A"}],"a":"E26-T05-89-91.mp3"},{"ns":[92,94],"script":[["W","Regular listeners of the Going Electric podcast may be familiar with today's guest because she was on the podcast last year. Dr. Mona Alamri is a leading transportation engineer. In today's episode, she'll be talking about electric ships that can operate with zero emissions. These high-speed ships may completely change the way people and goods are moved along the world's coastlines. But, before I welcome Dr. Alamri, please note there is a change to next month's schedule—most notably, I'll be on vacation for three weeks.","Những người nghe thường xuyên của podcast Going Electric có thể quen thuộc với vị khách hôm nay vì cô ấy đã xuất hiện năm ngoái. Tiến sĩ Mona Alamri là kỹ sư giao thông hàng đầu. Trong tập hôm nay, cô ấy sẽ nói về tàu điện có thể hoạt động không phát thải. Những con tàu tốc độ cao này có thể thay đổi hoàn toàn cách di chuyển người và hàng hóa dọc theo bờ biển thế giới. Nhưng trước khi chào đón Tiến sĩ Alamri, lưu ý có thay đổi trong lịch tháng tới—đáng chú ý nhất là tôi sẽ nghỉ phép ba tuần."]],"qs":[{"n":92,"q":"Who is Mona Alamri?","qvi":"Mona Alamri là ai?","opts":["A local official","A ship captain","A marine scientist","An engineer"],"vi":["Quan chức địa phương","Thuyền trưởng","Nhà khoa học hải dương","Kỹ sư"],"ans":"D"},{"n":93,"q":"What is the focus of today’s podcast episode?","qvi":"Chủ đề podcast hôm nay là gì?","opts":["Coastal mapping","Offshore wind farms","Electric ships","Bridge construction"],"vi":["Bản đồ bờ biển","Tuabin gió ngoài khơi","Tàu điện","Xây dựng cầu"],"ans":"C"},{"n":94,"q":"What does the speaker alert the listeners to?","qvi":"Người nói cảnh báo người nghe điều gì?","opts":["A schedule change","A volunteer opportunity","An updated Web site","A project start date"],"vi":["Lịch trình thay đổi","Cơ hội tình nguyện","Trang web cập nhật","Ngày bắt đầu dự án"],"ans":"A"}],"a":"E26-T05-92-94.mp3"},{"ns":[95,97],"script":[["M","Good morning, everyone, and welcome to the fifteenth annual Summerhaven Bicycle Race. The profits from this year's race will help our town fix the Grant Park footbridge, which is in serious need of maintenance. Please take a look at the map to familiarize yourselves with the route the cyclists will be taking. Remember, there's a beverage stand located between city hall and the art museum, so you can stay hydrated while you watch the race.","Chào buổi sáng mọi người, và chào mừng đến với Cuộc đua Xe đạp Summer Haven hàng năm lần thứ mười lăm. Lợi nhuận từ cuộc đua năm nay sẽ giúp thị trấn chúng ta sửa chữa cầu đi bộ Grant Park, đang rất cần bảo dưỡng. Vui lòng xem bản đồ để làm quen với lộ trình mà các tay đua sẽ đi. Nhớ nhé, có quầy đồ uống nằm giữa tòa thị chính và bảo tàng nghệ thuật, để bạn có thể giữ nước trong lúc xem đua."]],"qs":[{"n":95,"q":"Where are the listeners?","qvi":"Người nghe đang ở đâu?","opts":["At a bicycle race","At a marathon","At a parade","At a festival"],"vi":["Cuộc đua xe đạp","Cuộc chạy marathon","Cuộc diễu hành","Lễ hội"],"ans":"A"},{"n":96,"q":"What will proceeds from the event support?","qvi":"Tiền thu được từ sự kiện sẽ hỗ trợ việc gì?","opts":["Creating an athletic field","Renovating a city library","Repairing a bridge","Building a new playground"],"vi":["Xây dựng một sân thể thao","Cải tạo thư viện thành phố","Sửa chữa cầu","Xây sân chơi mới"],"ans":"C"},{"n":97,"q":"Look at the graphic. On which street does the speaker say the listeners can find a beverage stand?","qvi":"Nhìn vào hình. Người nói cho biết người nghe có thể tìm thấy quầy đồ uống trên đường nào?","opts":["Fifth Street","Rose Street","Spring Street","Dill Street"],"vi":["Fifth Street","Rose Street","Spring Street","Dill Street"],"ans":"B"}],"a":"E26-T05-95-97.mp3","img":"g95.png"},{"ns":[98,100],"script":[["M","In today's meeting, we'll discuss where we are in our software development process for Universal Banking. In-depth user research will help us create a better online banking application. Sarai will start by telling us about her research into Universal Banking's target customers. What features do they need in a banking app, and how comfortable are they with technology? But before Sarai begins her presentation, let me remind you that as summer begins next week, so do summer hours. You'll be able to stop working at 2:00 o'clock on Friday afternoons, so we'll be moving our regular meeting to Friday mornings.","Trong cuộc họp hôm nay, chúng ta sẽ thảo luận vị trí hiện tại trong quy trình phát triển phần mềm cho Universal Banking. Nghiên cứu người dùng sâu sẽ giúp chúng ta tạo ứng dụng ngân hàng trực tuyến tốt hơn. Sarai sẽ bắt đầu bằng cách kể về nghiên cứu của cô ấy về khách hàng mục tiêu của Universal Banking. Họ cần tính năng gì trong app ngân hàng, và họ thoải mái với công nghệ đến mức nào? Nhưng trước khi Sarai bắt đầu bài thuyết trình, để tôi nhắc rằng khi hè bắt đầu tuần tới, giờ hè cũng vậy. Bạn sẽ có thể ngừng làm việc lúc 2 giờ chiều thứ Sáu, nên chúng ta sẽ dời cuộc họp định kỳ sang sáng thứ Sáu."]],"qs":[{"n":98,"q":"What industry is the mobile app intended for?","qvi":"Ứng dụng di động thuộc ngành nào?","opts":["Entertainment","Travel","Education","Finance"],"vi":["Giải trí","Du lịch","Giáo dục","Tài chính"],"ans":"D"},{"n":99,"q":"Look at the graphic. Which stage of market research will Sarai talk about?","qvi":"Nhìn vào hình. Sarai sẽ nói về giai đoạn nào của nghiên cứu thị trường?","opts":["Stage 1","Stage 2","Stage 3","Stage 4"],"vi":["Giai đoạn 1","Giai đoạn 2","Giai đoạn 3","Giai đoạn 4"],"ans":"A"},{"n":100,"q":"What will begin next Friday?","qvi":"Điều gì sẽ bắt đầu vào thứ Sáu tới?","opts":["A seasonal work schedule","A business conference","A construction project","A contract negotiation"],"vi":["Lịch làm việc theo mùa","Hội nghị kinh doanh","Dự án xây dựng","Đàm phán hợp đồng"],"ans":"A"}],"a":"E26-T05-98-100.mp3","img":"g98.png"}]},"rc":{"p5":[{"n":101,"q":"Mr. Choi, who recently joined the advisory board, is an experienced accountant ------- investor.","opts":["but","that","and","yet"],"ans":"C","xp":"accountant and investor = kế toán và nhà đầu tư\nbut / yet: đối lập (sai nghĩa)\nthat: không nối danh từ\n→ Chọn (C)\nDịch: Ông Choi, người vừa gia nhập ban cố vấn, là một kế toán viên và nhà đầu tư giàu kinh nghiệm."},{"n":102,"q":"The first 150 visitors to the new fitness park will each receive a complimentary water -------.","opts":["bottle","bottled","bottling","to bottle"],"ans":"A","xp":"water bottle = chai nước\nbottled: tính từ\nbottling / to bottle: động từ\n→ Chọn (A)\nDịch: 150 khách đầu tiên đến công viên thể dục mới sẽ mỗi người nhận được một chai nước miễn phí."},{"n":103,"q":"Operating instructions for the printer will be e-mailed to employees -------.","opts":["short","shortly","shorter","shortening"],"ans":"B","xp":"shortly = sớm thôi\nshort: tính từ\nshorter: so sánh\nshortening: V-ing\n→ Chọn (B)\nDịch: Hướng dẫn sử dụng máy in sẽ sớm được gửi email cho nhân viên."},{"n":104,"q":"Dozens of ------- customers have posted positive reviews of Stellenbosch Cycle Works.","opts":["satisfy","satisfied","satisfaction","satisfies"],"ans":"B","xp":"satisfied customers = khách hàng hài lòng\nsatisfy: động từ\nsatisfaction: danh từ\nsatisfies: động từ\n→ Chọn (B)\nDịch: Hàng chục khách hàng hài lòng đã đăng đánh giá tích cực về Stellenbosch Cycle Works."},{"n":105,"q":"Ms. Lim’s best-selling novel has been ------- praised.","opts":["respectively","tightly","unhappily","widely"],"ans":"D","xp":"widely praised = được ca ngợi rộng rãi\nrespectively: tương ứng\ntightly: chặt chẽ\nunhappily: không vui\n→ Chọn (D)\nDịch: Cuốn tiểu thuyết bán chạy của cô Lim đã được ca ngợi rộng rãi."},{"n":106,"q":"The marketing manager, Ms. Abyola, plans to meet with the press following ------- meeting with the vice president.","opts":["her","she","hers","herself"],"ans":"A","xp":"her meeting = cuộc họp của cô ấy\nshe: chủ ngữ\nhers: đại từ sở hữu\nherself: phản thân\n→ Chọn (A)\nDịch: Quản lý marketing, cô Abyola, dự định gặp báo chí sau cuộc họp của cô ấy với phó chủ tịch."},{"n":107,"q":"Last weekend, Terriville Community Center held a ------- game night for neighborhood children.","opts":["removable","plentiful","lively","current"],"ans":"C","xp":"lively game night = đêm trò chơi sôi động\nremovable: có thể tháo\nplentiful: dồi dào\ncurrent: hiện tại\n→ Chọn (C)\nDịch: Cuối tuần trước, Trung tâm Cộng đồng Terriville đã tổ chức một đêm trò chơi sôi động cho trẻ em trong khu phố."},{"n":108,"q":"Mr. Lenthe will distribute ------- of the workshop agenda to all managers by Tuesday morning.","opts":["copies","copier","copy","copying"],"ans":"A","xp":"copies of = các bản sao\ncopier: máy photocopy\ncopy: số ít\ncopying: V-ing\n→ Chọn (A)\nDịch: Ông Lenthe sẽ phát các bản sao của chương trình hội thảo cho tất cả quản lý trước sáng thứ Ba."},{"n":109,"q":"Employees are eligible for more vacation time ------- they have been employed for five years.","opts":["after","neither","so","thus"],"ans":"A","xp":"after = sau khi\nneither: không… cũng không\nso / thus: kết quả\n→ Chọn (A)\nDịch: Nhân viên được hưởng thêm ngày nghỉ phép sau khi họ đã làm việc 5 năm."},{"n":110,"q":"Managers at Afton Accounting are urged to provide ------- feedback to employees on a regular basis.","opts":["construct","constructor","constructive","construction"],"ans":"C","xp":"constructive feedback = phản hồi mang tính xây dựng\nconstruct: động từ\nconstructor: danh từ chỉ người\nconstruction: danh từ\n→ Chọn (C)\nDịch: Các quản lý tại Afton Accounting được khuyến khích thường xuyên cung cấp phản hồi mang tính xây dựng cho nhân viên."},{"n":111,"q":"Many farmers markets operate on a seasonal -------, opening in spring and closing in late autumn.","opts":["topic","basis","root","sum"],"ans":"B","xp":"seasonal basis = theo mùa (on a seasonal basis)\ntopic / root / sum: sai nghĩa\n→ Chọn (B)\nDịch: Nhiều chợ nông sản hoạt động theo mùa, mở cửa vào mùa xuân và đóng cửa vào cuối thu."},{"n":112,"q":"------- in the housing market has continued to drag down real estate profits.","opts":["Weak","Weakly","Weakness","Weakened"],"ans":"C","xp":"Weakness = sự suy yếu (danh từ làm chủ ngữ)\nWeak: tính từ\nWeakly: trạng từ\nWeakened: quá khứ\n→ Chọn (C)\nDịch: Sự suy yếu trong thị trường nhà ở tiếp tục kéo lợi nhuận bất động sản đi xuống."},{"n":113,"q":"The sudden merger of Alvy Brothers and Craford Enterprises ------- most financial analysts.","opts":["enabled","arranged","surprised","suspected"],"ans":"C","xp":"surprised = làm ngạc nhiên\nenabled: cho phép\narranged: sắp xếp\nsuspected: nghi ngờ\n→ Chọn (C)\nDịch: Việc sáp nhập đột ngột của Alvy Brothers và Craford Enterprises đã khiến hầu hết chuyên gia tài chính ngạc nhiên."},{"n":114,"q":"Of all the mistakes people make in the office, not proofreading their e-mails is one of the -------.","opts":["commoners","most common","in common","more commonly"],"ans":"B","xp":"one of the most common = một trong những điều phổ biến nhất\ncommoners: thường dân\nin common: chung\nmore commonly: trạng từ\n→ Chọn (B)\nDịch: Trong tất cả các lỗi người ta mắc ở văn phòng, không đọc soát lại email là một trong những lỗi phổ biến nhất."},{"n":115,"q":"Cayfair Global’s ------- mission is to transport and deliver client goods in a timely manner.","opts":["prompt","primary","bright","nearest"],"ans":"B","xp":"primary mission = nhiệm vụ chính\nprompt: nhanh\nbright: sáng\nnearest: gần nhất\n→ Chọn (B)\nDịch: Sứ mệnh chính của Cayfair Global là vận chuyển và giao hàng hóa của khách hàng đúng hạn."},{"n":116,"q":"The department supervisor is ------- for ensuring that all safety gear is stowed properly at the end of the shift.","opts":["responsibilities","responsibility","responsibly","responsible"],"ans":"D","xp":"be responsible for = chịu trách nhiệm về\nresponsibilities: danh từ số nhiều\nresponsibility: danh từ\nresponsibly: trạng từ\n→ Chọn (D)\nDịch: Giám sát bộ phận chịu trách nhiệm đảm bảo mọi đồ bảo hộ được cất gọn đúng cách vào cuối ca."},{"n":117,"q":"A three-year project deepened the -------, allowing it to accommodate the largest cargo ships.","opts":["tide","boat","harbor","island"],"ans":"C","xp":"harbor = cảng\ntide / boat / island: sai nghĩa\n→ Chọn (C)\nDịch: Một dự án kéo dài ba năm đã nạo sâu cảng, giúp cảng có thể đón những tàu chở hàng lớn nhất."},{"n":118,"q":"The experiment’s initial results were ------- different from what was expected.","opts":["wild","wildest","wildly","wildness"],"ans":"C","xp":"wildly different = khác biệt hoàn toàn (trạng từ bổ nghĩa cho tính từ)\nwild: tính từ\nwildest: so sánh nhất\nwildness: danh từ\n→ Chọn (C)\nDịch: Kết quả ban đầu của thí nghiệm hoàn toàn khác với dự đoán."},{"n":119,"q":"------- critical reviews, the movie was a great success at the box office.","opts":["During","About","Despite","Over"],"ans":"C","xp":"Despite = mặc dù\nDuring: trong suốt\nAbout: về\nOver: trong suốt\n→ Chọn (C)\nDịch: Mặc dù có nhiều đánh giá tiêu cực, bộ phim vẫn rất thành công về doanh thu phòng vé."},{"n":120,"q":"The spray-on sealant ------- as a protective layer that keeps your tiles from getting scratched.","opts":["acts","acting","action","actively"],"ans":"A","xp":"acts as = hoạt động như (câu cần động từ chính)\nacting: V-ing\naction: danh từ\nactively: trạng từ\n→ Chọn (A)\nDịch: Chất phủ dạng xịt hoạt động như một lớp bảo vệ giúp gạch của bạn không bị trầy xước."},{"n":121,"q":"The contract for the renovation of the park will not be awarded ------- all bids have been submitted.","opts":["nor","next","until","because"],"ans":"C","xp":"not ... until = không ... cho đến khi\nnor / next / because: sai nghĩa\n→ Chọn (C)\nDịch: Hợp đồng cải tạo công viên sẽ không được trao cho đến khi tất cả hồ sơ dự thầu đã được nộp."},{"n":122,"q":"A recent study showed that substituting refined sugars with maple syrup may have some important ------- benefits.","opts":["only","full","legal","health"],"ans":"D","xp":"health benefits = lợi ích sức khỏe\nonly / full / legal: sai nghĩa\n→ Chọn (D)\nDịch: Một nghiên cứu gần đây cho thấy thay đường tinh luyện bằng siro phong có thể mang lại một số lợi ích sức khỏe quan trọng."},{"n":123,"q":"Margie Fung was ------- the winners at Sternetz Institute’s art competition.","opts":["from","upon","among","beyond"],"ans":"C","xp":"among the winners = trong số những người chiến thắng\nfrom / upon / beyond: sai\n→ Chọn (C)\nDịch: Margie Fung nằm trong số những người chiến thắng tại cuộc thi nghệ thuật của Viện Sternetz."},{"n":124,"q":"Posting updates too infrequently on social media can cause small businesses ------- by their customers.","opts":["forgets","to forget","been forgotten","to be forgotten"],"ans":"D","xp":"cause sb to be forgotten = khiến ai bị quên lãng (bị động, có “by”)\nforgets: chia sai\nto forget: chủ động\nbeen forgotten: thiếu “to be”\n→ Chọn (D)\nDịch: Đăng cập nhật quá thưa thớt trên mạng xã hội có thể khiến doanh nghiệp nhỏ bị khách hàng quên lãng."},{"n":125,"q":"Ideal for conference rooms, our soundproof panels have been specially designed to ------- unwanted background noise.","opts":["compete","absorb","surpass","remain"],"ans":"B","xp":"absorb noise = hấp thụ tiếng ồn\ncompete / surpass / remain: sai\n→ Chọn (B)\nDịch: Lý tưởng cho phòng hội nghị, các tấm cách âm của chúng tôi được thiết kế đặc biệt để hấp thụ tiếng ồn nền không mong muốn."},{"n":126,"q":"Mr. Sato will call into the meeting ------- the hotel’s wireless network.","opts":["used","using","use","had used"],"ans":"B","xp":"using = sử dụng (V-ing chỉ cách thức)\nused / use / had used: sai cấu trúc\n→ Chọn (B)\nDịch: Ông Sato sẽ gọi vào cuộc họp bằng mạng không dây của khách sạn."},{"n":127,"q":"Not only has Mr. Ogbu ------- worked on the project, but he has also trained Ms. Jeong to continue the work.","opts":["accessibly","diligently","eventfully","completely"],"ans":"B","xp":"diligently worked = làm việc chăm chỉ\naccessibly: dễ tiếp cận\neventfully: đầy sự kiện\ncompletely: hoàn toàn\n→ Chọn (B)\nDịch: Ông Ogbu không chỉ làm việc chăm chỉ cho dự án mà còn đào tạo cô Jeong để tiếp tục công việc."},{"n":128,"q":"Belker Auto offers a ten-year warranty for ------- who want greater peace of mind.","opts":["this","those","somebody","everyone"],"ans":"B","xp":"those who = những người mà (động từ “want” số nhiều)\nthis / somebody / everyone: không phù hợp\n→ Chọn (B)\nDịch: Belker Auto cung cấp bảo hành mười năm dành cho những người muốn yên tâm hơn."},{"n":129,"q":"After months of planning, the Lanton Bookstore school reading program will finally ------- in October.","opts":["observe","represent","commence","access"],"ans":"C","xp":"commence = bắt đầu (trang trọng)\nobserve / represent / access: sai\n→ Chọn (C)\nDịch: Sau nhiều tháng lên kế hoạch, chương trình đọc sách cho trường học của Hiệu sách Lanton cuối cùng sẽ bắt đầu vào tháng 10."},{"n":130,"q":"Independent consultants can be a valuable source of ------- advice to new entrepreneurs.","opts":["unfulfilled","indefinite","obedient","impartial"],"ans":"D","xp":"impartial advice = lời khuyên khách quan\nunfulfilled / indefinite / obedient: sai nghĩa\n→ Chọn (D)\nDịch: Các chuyên gia tư vấn độc lập có thể là nguồn lời khuyên khách quan quý giá cho các doanh nhân mới."}],"p6":[{"ns":[131,134],"head":"Questions 131-134 refer to the following e-mail.","passage":"<div class=\"hdr\"><p><b>To:</b> Creative Team</p><p><b>From:</b> Camille Patel</p><p><b>Date:</b> December 9</p><p><b>Re:</b> Colleague departure</p></div><p>Dear Team Members,</p><p>As many of you have recently learned, Claudia Hoffman will end her tenure as art director on Monday, December 30. After ten years in this <span class=\"blank\" data-n=\"131\">-------</span>, she will be taking on a new professional challenge in Paris. <span class=\"blank\" data-n=\"132\">-------</span>, she will join the leadership team at a top advertising agency. Marcos Molina from Spencer Design will become our new art director. <span class=\"blank\" data-n=\"133\">-------</span>.</p><p>I would like to personally thank Ms. Hoffman for her tremendous leadership. She <span class=\"blank\" data-n=\"134\">-------</span> a key factor in our agency’s success. Please join me in celebrating her achievements at a farewell dinner after work hours on Friday, December 27. The details will be forthcoming.</p><p>Sincerely,</p><p>Camille Patel<br>Human Resources Officer</p>","vi":"Đến: Nhóm Sáng tạo\nTừ: Camille Patel\nNgày: 9 tháng 12\nV/v: Đồng nghiệp nghỉ việc\n\nGửi Nhóm Sáng tạo,\n\nNhư nhiều người trong số các bạn mới biết, Claudia Hoffman sẽ kết thúc nhiệm kỳ giám đốc nghệ thuật của mình vào thứ Hai, ngày 30 tháng 12. Sau mười năm ở vai trò này, cô ấy sẽ đón nhận một thử thách chuyên môn mới tại Paris. Tại đó, cô ấy sẽ gia nhập đội ngũ lãnh đạo tại một công ty quảng cáo hàng đầu. Marcos Molina từ Spencer Design sẽ trở thành giám đốc nghệ thuật mới của chúng ta. Anh ấy sẽ bắt đầu làm việc với chúng ta vào ngày 12 tháng 1.\n\nTôi muốn đích thân cảm ơn cô Hoffman vì sự lãnh đạo tuyệt vời của cô. Cô đã là một nhân tố then chốt dẫn đến thành công của công ty chúng ta. Hãy cùng tôi chúc mừng những thành tựu của cô ấy tại một bữa tối chia tay sau giờ làm việc vào thứ Sáu, ngày 27 tháng 12. Chi tiết sẽ sớm được thông báo.\n\nTrân trọng,\n\nCamille Patel\nNhân viên Nhân sự","qs":[{"n":131,"opts":["role","school","production","warehouse"],"ans":"A","xp":"(A) role: vai trò\nNgữ cảnh: \"...ten years in this role\" (10 năm ở vai trò này).\nGiải thích: \"Role\" (vai trò/vị trí) thường dùng để chỉ công việc trong một công ty. Các từ khác như school (trường), production (sản xuất), warehouse (kho) không phù hợp với chức danh \"art director\" (giám đốc nghệ thuật) đã nhắc ở đầu câu.\n→ Chọn (A)"},{"n":132,"opts":["There","Instead","Otherwise","Afterward"],"ans":"A","xp":"(A) There: ở đó\nNgữ cảnh: Câu trước nhắc đến \"Paris\". Câu sau: \"There, she will join...\"\nGiải thích: Đây là trạng từ chỉ nơi chốn dùng để thay thế cho danh từ riêng vừa nhắc trước đó nhằm tránh lặp từ.\nLoại trừ: Instead (thay vào đó), Otherwise (nếu không thì), Afterward (sau đó) không phù hợp về logic vị trí địa lý.\n→ Chọn (A)"},{"n":133,"opts":["Let him know if you would like to apply.","The salary levels are more competitive.","He will be joining us on January 12.","Spencer Design has lost revenue over the last two years."],"ans":"C","xp":"(C) He will be joining us on January 12. (Anh ấy sẽ bắt đầu làm việc với chúng ta vào ngày 12 tháng 1.)\nNgữ cảnh: Câu trước giới thiệu người mới (Marcos Molina).\nGiải thích: Theo mạch văn thông báo nhân sự, sau khi giới thiệu tên người mới sẽ là thông tin về ngày bắt đầu làm việc. Các phương án còn lại (mức lương, việc công ty cũ mất doanh thu...) đều không liên quan đến nội dung chúc mừng.\n→ Chọn (C)"},{"n":134,"opts":["will be","could be","has been","would have been"],"ans":"C","xp":"(C) has been\nNgữ cảnh: \"She has been a key factor...\"\nGiải thích: Claudia đã làm việc 10 năm và sắp nghỉ. Ta dùng thì Hiện tại hoàn thành để nói về một hành động/trạng thái kéo dài từ quá khứ đến hiện tại.\n→ Chọn (C)"}]},{"ns":[135,138],"head":"Questions 135-138 refer to the following booklet.","passage":"<h3>The Tominos Team Leadership Seminar</h3><p>Your success <span class=\"blank\" data-n=\"135\">-------</span> a team leader depends on your ability to consistently inspire your team members to perform at the highest level. Good leaders know how to find viable solutions to workplace problems and implement them accordingly. <span class=\"blank\" data-n=\"136\">-------</span>. How can you gain these skills?</p><p>In this seminar, you <span class=\"blank\" data-n=\"137\">-------</span> how to better align your team members’ performance with your organization’s goals. <span class=\"blank\" data-n=\"138\">-------</span> in the seminar acquire proven tools and techniques for successfully directing a team in today’s fast-paced business environment.</p>","vi":"Hội thảo Lãnh đạo Nhóm Tominos\n\nSự thành công của bạn với tư cách là một trưởng nhóm phụ thuộc vào khả năng truyền cảm hứng liên tục cho các thành viên trong nhóm để họ đạt được hiệu suất cao nhất. Những nhà lãnh đạo giỏi biết cách tìm ra các giải pháp khả thi cho các vấn đề tại nơi làm việc và thực hiện chúng một cách phù hợp. Họ giao tiếp với nhóm của mình thường xuyên để giúp mọi người nắm bắt thông tin. Làm thế nào bạn có thể đạt được những kỹ năng này?\n\nTrong hội thảo này, bạn sẽ học cách điều chỉnh tốt hơn hiệu suất của các thành viên trong nhóm với mục tiêu của tổ chức. Những người tham gia hội thảo sẽ có được các công cụ và kỹ thuật đã được kiểm chứng để điều hành một đội nhóm thành công trong môi trường kinh doanh nhịp độ nhanh ngày nay.","qs":[{"n":135,"opts":["where","therefore","for","as"],"ans":"D","xp":"(D) as: với tư cách là\nCấu trúc: Success as + [Chức danh/Vị trí].\nGiải thích: \"As\" ở đây đóng vai trò là giới từ mang nghĩa \"với tư cách là\". (Thành công với tư cách là một trưởng nhóm).\n→ Chọn (D)"},{"n":136,"opts":["One common problem is employee tardiness.","Our seminars cost £120 per session.","They communicate with their team regularly to keep them informed.","Sign up now and receive a ten percent discount on the registration fee."],"ans":"C","xp":"(C) They communicate with their team regularly to keep them informed. (Họ giao tiếp với nhóm của mình thường xuyên để giúp mọi người nắm bắt thông tin.)\nNgữ cảnh: Câu trước nói: \"Good leaders know how to find... and implement...\" (Lãnh đạo giỏi biết cách tìm... và thực hiện...).\nGiải thích: Câu này cần một hành động tiếp theo của \"Good leaders\". Việc \"giao tiếp thường xuyên\" là một đặc điểm của lãnh đạo giỏi.\nLoại trừ: Câu (A) nói về việc nhân viên đi muộn, (B) nói về giá cả, (D) nói về giảm giá - tất cả đều làm ngắt mạch định nghĩa về người lãnh đạo.\n→ Chọn (C)"},{"n":137,"opts":["learned","will learn","had learned","will have learned"],"ans":"B","xp":"(B) will learn\nDấu hiệu: \"In this seminar...\" (Trong hội thảo này - sắp diễn ra).\nGiải thích: Đây là lời hứa hẹn về kết quả sau khi tham gia, nên dùng thì Tương lai đơn.\n→ Chọn (B)"},{"n":138,"opts":["Authorities","Candidates","Participants","Subscribers"],"ans":"C","xp":"(C) Participants: người tham gia\nNgữ cảnh: \"...in the seminar acquire proven tools...\"\nGiải thích: Người tham gia hội thảo (Participants) là những người sẽ nhận được giá trị.\nPhân biệt: Authorities (chính quyền), Candidates (ứng viên xin việc), Subscribers (người đăng ký tạp chí/kênh).\n→ Chọn (C)"}]},{"ns":[139,142],"head":"Questions 139-142 refer to the following e-mail.","passage":"<div class=\"hdr\"><p><b>To:</b> Kana Inoue &lt;kana.inoue@mymail.co.uk&gt;</p><p><b>From:</b> Brian Halstan &lt;bhalstan@impressionise.co.uk&gt;</p><p><b>Date:</b> 9 May</p><p><b>Subject:</b> Free consultation offer</p></div><p>Dear Ms. Inoue,</p><p>I am writing on behalf of Impressionise. We are a design firm specialising in medical facilities: waiting rooms, offices, and examination and therapy rooms. Our research indicates that you are planning to open a physiotherapy practice in Queen’s Point <span class=\"blank\" data-n=\"139\">-------</span> the next few months. No doubt, you want your facilities to be comfortable and calming while enhancing your professional practice and conforming to your brand image. <span class=\"blank\" data-n=\"140\">-------</span>. We would love to work with you to create an inviting <span class=\"blank\" data-n=\"141\">-------</span> that you can be proud of. You can view photographs of our <span class=\"blank\" data-n=\"142\">-------</span> projects at www.impressionise.co.uk/portfolio. If interested, please reply to this e-mail to schedule a free consultation.</p><p>Sincerely,</p><p>Brian Halstan, Sales Manager<br>Impressionise</p>","vi":"Đến: Kana Inoue <kana.inoue@mymail.co.uk>\nTừ: Brian Halstan <bhalstan@impressionise.co.uk>\nNgày: 9 tháng 5\nTiêu đề: Ưu đãi tư vấn miễn phí\n\nKính gửi cô Inoue,\n\nTôi viết thư này thay mặt cho Impressionise. Chúng tôi là một công ty thiết kế chuyên về các cơ sở y tế: phòng chờ, văn phòng, phòng khám và phòng trị liệu. Nghiên cứu của chúng tôi cho thấy bạn đang có kế hoạch mở một phòng tập vật lý trị liệu tại Queen's Point trong vòng vài tháng tới. Chắc chắn, bạn muốn cơ sở của mình thật thoải mái và nhẹ nhàng trong khi vẫn nâng cao uy tín chuyên môn và phù hợp với hình ảnh thương hiệu của bạn. Hãy để chúng tôi giúp bạn đạt được những mục tiêu này. Chúng tôi rất mong được hợp tác với bạn để tạo ra một không gian thân thiện mà bạn có thể tự hào. Bạn có thể xem ảnh về các dự án trước đây của chúng tôi tại trang web www.impressionise.co.uk/portfolio. Nếu quan tâm, vui lòng trả lời email này để đặt lịch tư vấn miễn phí.\n\nTrân trọng,\n\nBrian Halstan, Quản lý Bán hàng\nImpressionise","qs":[{"n":139,"opts":["either","perhaps","within","since"],"ans":"C","xp":"(C) within: trong vòng\nDấu hiệu: \"...within the next few months\" (trong vòng vài tháng tới).\nGiải thích: \"Within\" là giới từ chỉ một khoảng thời gian mà hành động sẽ xảy ra bên trong giới hạn đó.\n→ Chọn (C)"},{"n":140,"opts":["Let us help you achieve these objectives.","Ask us about potential tax advantages.","Our software makes booking appointments easy.","A well-trained staff is all you need to succeed."],"ans":"A","xp":"(A) Let us help you achieve these objectives. (Hãy để chúng tôi giúp bạn đạt được những mục tiêu này.)\nDấu hiệu: \"these objectives\" (những mục tiêu này).\nGiải thích: \"Objectives\" ở đây ám chỉ việc làm cho cơ sở \"thoải mái, làm dịu, nâng cao hình ảnh\" đã nêu ở câu trước. Đây là cách kết nối ý rất phổ biến trong Part 6.\n→ Chọn (A)"},{"n":141,"opts":["space","event","signal","moment"],"ans":"A","xp":"(A) space: không gian\nNgữ cảnh: \"an inviting space\" (một không gian thân thiện).\nGiải thích: Công ty này là công ty thiết kế nội thất cho phòng khám, nên sản phẩm họ tạo ra là \"không gian\".\n→ Chọn (A)"},{"n":142,"opts":["educational","residential","preventive","previous"],"ans":"D","xp":"(D) previous: trước đây\nCụm từ cố định: Previous projects (các dự án trước đây).\nGiải thích: Khi giới thiệu năng lực (Portfolio), các công ty thường đưa ra ảnh các công trình họ đã làm xong trong quá khứ.\nLoại trừ: educational (giáo dục), residential (nhà ở), preventive (phòng ngừa).\n→ Chọn (D)"}]},{"ns":[143,146],"head":"Questions 143-146 refer to the following information.","passage":"<p><i>Digital Chicory</i> is a monthly magazine that provides resources and tutorials for Web designers. <i>Digital Chicory</i> accepts informative and well-written articles of 800 to 1,200 words. <span class=\"blank\" data-n=\"143\">-------</span>. If you have an idea for an article, please send your pitch to writer@digitalchicory.org. <span class=\"blank\" data-n=\"144\">-------</span>, be sure to spend some time reading our publication so that you can develop an understanding of our audience and general writing style. <span class=\"blank\" data-n=\"145\">-------</span> respond promptly to article proposals, which should be submitted as single-page outlines. Full-length <span class=\"blank\" data-n=\"146\">-------</span> are typically discouraged at the proposal stage. However, if you are a new writer for our magazine, please include samples of previously published writing.</p>","vi":"Digital Chicory là một tạp chí hàng tháng cung cấp tài nguyên và hướng dẫn cho các nhà thiết kế Web. Digital Chicory chấp nhận các bài viết giàu thông tin và được viết tốt từ 800 đến 1.200 từ. Những bài viết dài hơn đôi khi cũng được xem xét. Nếu bạn có ý tưởng cho một bài báo, vui lòng gửi ý tưởng đó tới địa chỉ writer@digitalchicory.org. Trước khi bạn làm vậy, hãy chắc chắn dành thời gian đọc ấn phẩm của chúng tôi để bạn có thể hiểu về độc giả và phong cách viết chung của chúng tôi. Chúng tôi phản hồi nhanh chóng các đề xuất bài viết, những đề xuất này nên được gửi dưới dạng tóm tắt một trang. Các bản thảo đầy đủ thường không được khuyến khích ở giai đoạn đề xuất. Tuy nhiên, nếu bạn là người mới viết cho tạp chí của chúng tôi, vui lòng gửi kèm các bài viết đã xuất bản trước đây của bạn.","qs":[{"n":143,"opts":["Lengthier articles are sometimes considered as well.","The editorial staff has won numerous awards.","Subscribe now and receive a free tote bag.","Please allow four to six weeks for delivery."],"ans":"A","xp":"(A) Lengthier articles are sometimes considered as well. (Những bài viết dài hơn đôi khi cũng được xem xét.)\nNgữ cảnh: Câu trước giới hạn 800-1200 từ.\nGiải thích: Câu này bổ sung ngoại lệ (các bài dài hơn cũng có thể được xem xét). \"As well\" ở cuối câu là dấu hiệu của việc bổ sung thông tin.\n→ Chọn (A)"},{"n":144,"opts":["In any event","If you cannot","Before you do","On the contrary"],"ans":"C","xp":"(C) Before you do: trước khi bạn làm vậy\nNgữ cảnh: Câu trước bảo gửi ý tưởng (pitch). Câu sau bảo đọc tạp chí.\nGiải thích: \"Before you do (so)\" = Trước khi bạn gửi ý tưởng đó. Đây là lời khuyên về quy trình.\n→ Chọn (C)"},{"n":145,"opts":["We","They","Some","These"],"ans":"A","xp":"(A) We: chúng tôi\nNgữ cảnh: \"...respond promptly to article proposals.\"\nGiải thích: Chủ ngữ thực hiện hành động \"phản hồi\" (respond) bài viết của cộng tác viên phải là \"Chúng tôi\" (Ban biên tập tạp chí).\n→ Chọn (A)"},{"n":146,"opts":["forms","drafts","contracts","schedules"],"ans":"B","xp":"(B) drafts: bản thảo\nNgữ cảnh: \"Full-length drafts\" (Bản thảo đầy đủ).\nGiải thích: Trong quy trình xuất bản, bước đầu là gửi outline (dàn ý), bước sau là draft (bản thảo). Tòa soạn khuyên không nên gửi bản thảo đầy đủ ngay từ đầu.\n→ Chọn (B)"}]}],"p7":[{"ns":[147,148],"head":"Questions 147-148 refer to the following information.","passages":["<h3>Your Business Gets Noticed When You Advertise Here!</h3><p>Prime advertising space is available with sizes ranging from a quarter column to a full page. The <i>Clearpoint Times</i> reaches thousands of your neighbors each week. Use the <i>Clearpoint Times</i> to spread the word about your business. It works! For rates and additional information, call us at 515-555-0130.</p>"],"vi":"Doanh nghiệp của bạn sẽ được chú ý khi bạn quảng cáo tại đây!\n\nChúng tôi có sẵn vị trí quảng cáo đắc địa với nhiều kích cỡ khác nhau, từ một phần tư cột cho đến nguyên một trang. Tờ Clearpoint Times tiếp cận hàng nghìn người dân trong khu vực của bạn mỗi tuần. Hãy sử dụng Clearpoint Times để quảng bá doanh nghiệp của bạn. Hiệu quả đã được chứng minh! Để biết bảng giá và thông tin chi tiết, vui lòng gọi cho chúng tôi theo số 515-555-0130.","qs":[{"n":147,"q":"What is the main purpose of the information?","qvi":"Mục đích chính của thông tin này là gì?","opts":["To announce the opening of a new business","To publicize storage spaces available for rent","To attract people who want to promote their businesses","To encourage people to buy newspaper subscriptions"],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Tiêu đề \"Your Business Gets Noticed When You Advertise Here!\" và câu \"Use the Clearpoint Times to spread the word about your business\" (Hãy dùng Clearpoint Times để quảng bá doanh nghiệp của bạn) → mục đích là thu hút người muốn quảng cáo doanh nghiệp.\n(A) Thông báo về việc khai trương một doanh nghiệp mới\n(B) Quảng bá các không gian lưu trữ đang cho thuê\n(C) Thu hút những người muốn quảng bá doanh nghiệp của họ\n(D) Khuyến khích mọi người mua báo dài hạn"},{"n":148,"q":"What is suggested about the Clearpoint Times?","qvi":"Điều gì được gợi ý về Clearpoint Times?","opts":["It is currently for sale.","It is a real estate magazine.","It is a local weekly publication.","It is a national daily newspaper."],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: \"The Clearpoint Times reaches thousands of your neighbors each week\" (tiếp cận hàng nghìn người dân trong khu vực của bạn mỗi tuần) → neighbors = địa phương, each week = hàng tuần.\n(A) Hiện đang được rao bán\n(B) Là một tạp chí bất động sản\n(C) Là một ấn phẩm địa phương phát hành hàng tuần\n(D) Là một tờ báo quốc gia phát hành hằng ngày"}]},{"ns":[149,150],"head":"Questions 149-150 refer to the following e-mail.","passages":["<div class=\"hdr\"><p><b>To:</b> Donna Witt &lt;d.witt@seemail.net&gt;; Jack Witt &lt;j.witt@seemail.net&gt;</p><p><b>From:</b> David Paltz &lt;dpaltz@emeraldglen.com&gt;</p><p><b>Date:</b> August 5</p><p><b>Subject:</b> Barkley Drive patio project</p></div><p>Hello, Donna and Jack,</p><p>I am just checking in as I finalize my schedule for the upcoming months. I would like to schedule a time to revisit your property and discuss your landscaping project in more detail. To get started, it would be helpful if the two of you could brainstorm some of your design expectations and overall vision for the project. Your ideas will help me better determine the materials and time needed. I can then give a more accurate price estimate.</p><p>David Paltz<br>Emerald Glen Landscaping</p>"],"vi":"Gửi: Donna Witt; Jack Witt\nTừ: David Paltz\nNgày: 5 tháng 8\nChủ đề: Dự án sân hiên đường Barkley\n\nChào Donna và Jack,\n\nTôi viết thư này để kiểm tra lại khi tôi đang hoàn thiện lịch làm việc của mình cho những tháng sắp tới. Tôi muốn sắp xếp một buổi hẹn để quay lại thăm khu nhà của anh chị và thảo luận chi tiết hơn về dự án cảnh quan của anh chị. Để bắt đầu, sẽ rất hữu ích nếu hai anh chị có thể cùng nhau trao đổi và đưa ra một số mong đợi về thiết kế cũng như tầm nhìn tổng thể cho dự án. Những ý tưởng của anh chị sẽ giúp tôi xác định tốt hơn các vật liệu cần dùng và thời gian thực hiện. Từ đó, tôi có thể đưa ra một bản ước tính chi phí chính xác hơn.\n\nDavid Paltz\nCông ty Cảnh quan Emerald Glen","qs":[{"n":149,"q":"What is the purpose of the e-mail?","qvi":"Mục đích của email là gì?","opts":["To request a meeting","To confirm a recent price change","To apologize for a scheduling delay","To seek additional staff for some work"],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: \"I would like to schedule a time to revisit your property and discuss your landscaping project in more detail\" (Tôi muốn sắp xếp một buổi hẹn để quay lại thăm khu nhà và thảo luận chi tiết hơn) → yêu cầu một cuộc gặp.\n(A) Yêu cầu một cuộc họp\n(B) Xác nhận một thay đổi giá gần đây\n(C) Xin lỗi vì sự chậm trễ trong việc sắp xếp lịch\n(D) Tìm thêm nhân sự cho một số công việc"},{"n":150,"q":"What does Mr. Paltz ask Mr. and Ms. Witt to do?","qvi":"Ông Paltz yêu cầu ông và bà Witt làm gì?","opts":["Submit a payment","Reschedule a work project","Avoid parking near a job site","Provide him with landscaping ideas"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: \"it would be helpful if the two of you could brainstorm some of your design expectations and overall vision for the project. Your ideas will help me...\" (sẽ rất hữu ích nếu hai anh chị đưa ra mong đợi về thiết kế... Ý tưởng của anh chị sẽ giúp tôi) → ông muốn họ cung cấp ý tưởng cảnh quan.\n(A) Gửi một khoản thanh toán\n(B) Sắp xếp lại lịch cho một dự án công việc\n(C) Tránh đỗ xe gần khu vực công trình\n(D) Cung cấp cho ông các ý tưởng về cảnh quan"}]},{"ns":[151,152],"head":"Questions 151-152 refer to the following advertisement.","passages":["<h3>Cavalina Hotel</h3><p><i>Blue Globe Magazine’s “Best Hotel” Award Winner!</i></p><p>Cavalina Hotel is a breathtaking sanctuary where guests can escape the hectic bustle of city life. Located 50 kilometers from the international airport in Jeel City, the hotel faces the beautiful Sea Mariner Bay. Windsurfing, paddleboarding, and several hiking and biking trails are all a short walk from our front door. Our knowledgeable staff are happy to arrange a kayaking excursion or a fishing trip to one of the nearby lakes. After a good night’s sleep in one of our comfortable rooms, you’ll be eager to explore the region right after breakfast!</p><p><b>Property Amenities:</b> free parking, swimming pool, bicycle rental, fitness center, two restaurants</p><p><b>Room Types:</b> single room, two-room suite with balcony, two-room suite with kitchen</p>"],"vi":"Khách sạn Cavalina\nNgười chiến thắng giải thưởng “Khách sạn tốt nhất” của tạp chí Blue Globe!\n\nKhách sạn Cavalina là một chốn nghỉ dưỡng tuyệt đẹp, nơi du khách có thể tránh xa sự ồn ào, hối hả của cuộc sống thành phố. Tọa lạc cách sân bay quốc tế tại thành phố Jeel 50 km, khách sạn hướng ra vịnh Sea Mariner xinh đẹp. Các hoạt động như lướt ván buồm, chèo ván đứng, cùng nhiều tuyến đường đi bộ đường dài và đạp xe đều chỉ cách cửa chính của chúng tôi một quãng đi bộ ngắn. Đội ngũ nhân viên am hiểu của chúng tôi luôn sẵn sàng sắp xếp cho quý khách một chuyến chèo thuyền kayak hoặc chuyến câu cá tại một trong những hồ nước gần đó. Sau một giấc ngủ ngon trong một trong những phòng nghỉ tiện nghi của khách sạn, quý khách sẽ háo hức khám phá khu vực xung quanh ngay sau bữa sáng!\n\nTiện nghi của khách sạn: bãi đỗ xe miễn phí, hồ bơi, dịch vụ cho thuê xe đạp, trung tâm thể dục, hai nhà hàng\n\nCác loại phòng: phòng đơn, phòng suite hai phòng có ban công, phòng suite hai phòng có bếp","qs":[{"n":151,"q":"For whom is the advertisement most likely intended?","qvi":"Quảng cáo này nhiều khả năng hướng tới đối tượng nào?","opts":["People who want to tour Jeel City","People who enjoy outdoor activities","Business conference organizers","Hotel industry professionals"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: \"guests can escape the hectic bustle of city life\" và \"Windsurfing, paddleboarding, and several hiking and biking trails are all a short walk from our front door\" (lướt ván buồm, chèo ván đứng, đường đi bộ đường dài và đạp xe ngay gần cửa) + kayak, câu cá → dành cho người thích hoạt động ngoài trời.\n(A) Những người muốn tham quan thành phố Jeel\n(B) Những người yêu thích các hoạt động ngoài trời\n(C) Những người tổ chức hội nghị doanh nghiệp\n(D) Những người làm trong ngành khách sạn"},{"n":152,"q":"What is suggested about some of the rooms at Cavalina Hotel?","qvi":"Điều gì được gợi ý về một số phòng tại khách sạn Cavalina?","opts":["They contain antique furniture.","They have recently been updated.","Guests can view them online.","Guests can prepare food in them."],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: \"Room Types: ... two-room suite with kitchen\" (phòng suite hai phòng có bếp) → có bếp nên khách có thể tự nấu ăn (prepare food).\n(A) Chúng có đồ nội thất cổ\n(B) Chúng vừa được nâng cấp gần đây\n(C) Khách có thể xem các phòng này trực tuyến\n(D) Khách có thể tự chuẩn bị đồ ăn trong phòng"}]},{"ns":[153,154],"head":"Questions 153-154 refer to the following text-message chain.","passages":["<div class=\"msg\"><p><b>Paul Cho (9:47 A.M.)</b></p><p>Hi, Marisol. I wanted to let you know that I was talking to the director of Yadav Digital Marketing, Elise Mayer. There’s an open position there, and I mentioned you. She says you should definitely apply.</p></div><div class=\"msg\"><p><b>Marisol Rosetti (9:49 A.M.)</b></p><p>That’s wonderful to hear! Thanks for passing my name along.</p></div><div class=\"msg\"><p><b>Paul Cho (9:50 A.M.)</b></p><p>I know you’d be a great fit. You check all the boxes.</p></div><div class=\"msg\"><p><b>Marisol Rosetti (9:51 A.M.)</b></p><p>Do you think Ms. Mayer would want to see a cover letter in addition to my résumé?</p></div><div class=\"msg\"><p><b>Paul Cho (9:52 A.M.)</b></p><p>I wouldn’t bother. Elise and I have been friends for years. Just make sure your résumé is up to date and reflects your relevant experience.</p></div><div class=\"msg\"><p><b>Marisol Rosetti (9:53 A.M.)</b></p><p>I’ll do that. Thank you so much, Paul. I really appreciate it!</p></div>"],"vi":"Paul Cho (9:47 sáng): Chào Marisol. Tôi muốn cho bạn biết là tôi vừa nói chuyện với giám đốc của công ty Yadav Digital Marketing, Elise Mayer. Ở đó đang có một vị trí tuyển dụng, và tôi đã nhắc đến bạn. Cô ấy nói rằng bạn chắc chắn nên nộp đơn ứng tuyển.\n\nMarisol Rosetti (9:49 sáng): Tin tuyệt vời quá! Cảm ơn anh đã giới thiệu tên tôi nhé.\n\nPaul Cho (9:50 sáng): Tôi biết bạn sẽ rất phù hợp. Bạn đáp ứng đầy đủ các yêu cầu.\n\nMarisol Rosetti (9:51 sáng): Anh có nghĩ là cô Mayer sẽ muốn xem thư xin việc kèm theo hồ sơ xin việc của tôi không?\n\nPaul Cho (9:52 sáng): Tôi nghĩ không cần đâu. Elise và tôi là bạn bè nhiều năm rồi. Chỉ cần đảm bảo rằng hồ sơ xin việc của bạn được cập nhật và thể hiện rõ kinh nghiệm liên quan là được.\n\nMarisol Rosetti (9:53 sáng): Tôi sẽ làm vậy. Cảm ơn anh rất nhiều, Paul. Tôi thực sự rất cảm kích!","qs":[{"n":153,"q":"At 9:50 A.M., what does Mr. Cho most likely mean when he writes, “I know you’d be a great fit”?","qvi":"Vào lúc 9:50 sáng, ông Cho nhiều khả năng muốn nói gì khi viết “I know you’d be a great fit”?","opts":["He would like to hire Ms. Rosetti.","He has worked at Yadav Digital Marketing for a long time.","He thinks Yadav Digital Marketing needs a new director.","He thinks Ms. Rosetti is a good candidate for a job."],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: Ông Cho vừa giới thiệu bà Rosetti cho vị trí đang tuyển, rồi nói \"I know you’d be a great fit. You check all the boxes.\" (Tôi biết bạn sẽ rất phù hợp. Bạn đáp ứng đầy đủ các yêu cầu.) → ông nghĩ bà là ứng viên tốt. (A) sai vì người tuyển là Elise Mayer, không phải ông Cho.\n(A) Ông muốn tuyển dụng bà Rosetti\n(B) Ông đã làm việc tại Yadav Digital Marketing trong một thời gian dài\n(C) Ông nghĩ rằng Yadav Digital Marketing cần một giám đốc mới\n(D) Ông nghĩ bà Rosetti là một ứng viên phù hợp cho công việc"},{"n":154,"q":"What is indicated about Mr. Cho?","qvi":"Điều gì được cho biết về ông Cho?","opts":["He has known Ms. Mayer for a long time.","He works at the same company as Ms. Mayer.","He will help Ms. Rosetti write a cover letter.","He is a director at a marketing firm."],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: \"Elise and I have been friends for years.\" (Elise và tôi là bạn bè nhiều năm rồi.) → quen biết bà Mayer từ lâu.\n(A) Ông đã quen biết bà Mayer từ lâu\n(B) Ông làm việc cùng công ty với bà Mayer\n(C) Ông sẽ giúp bà Rosetti viết thư xin việc\n(D) Ông là giám đốc tại một công ty tiếp thị"}]},{"ns":[155,157],"head":"Questions 155-157 refer to the following article.","passages":["<h3>Product Launch Delayed</h3><p>Covered Bridge Industries has delayed the launch of its new Balmy Breeze soft drink. The company had planned to release the product in June to take advantage of the higher sales demand during the summer months. The company said the delay was caused by a shortage of one of the drink’s main components, mango extract, which led to the postponement of quality testing until August.</p><p>Covered Bridge now hopes to complete all quality testing by November so that it can launch the product the following month. While sales will likely be weaker than originally hoped, the company will promote Balmy Breeze as an excellent choice for winter holiday celebrations.</p>"],"vi":"Việc Ra Mắt Sản Phẩm Bị Trì Hoãn\n\nCông ty Covered Bridge Industries đã trì hoãn việc ra mắt loại nước giải khát mới mang tên Balmy Breeze. Ban đầu, công ty dự định tung sản phẩm ra thị trường vào tháng Sáu để tận dụng nhu cầu mua sắm cao hơn trong các tháng mùa hè. Công ty cho biết sự trì hoãn này là do tình trạng thiếu hụt một trong những thành phần chính của đồ uống — chiết xuất xoài — điều này đã dẫn đến việc dời thời gian kiểm tra chất lượng sang tháng Tám.\n\nHiện nay, Covered Bridge hy vọng sẽ hoàn tất toàn bộ quá trình kiểm tra chất lượng vào tháng Mười Một để có thể ra mắt sản phẩm vào tháng tiếp theo. Mặc dù doanh số bán hàng có thể sẽ thấp hơn so với kỳ vọng ban đầu, công ty vẫn sẽ quảng bá Balmy Breeze như một lựa chọn tuyệt vời cho các dịp lễ hội mùa đông.","qs":[{"n":155,"q":"What kind of company most likely is Covered Bridge Industries?","qvi":"Covered Bridge Industries nhiều khả năng là loại công ty nào?","opts":["An ice cream producer","An advertising agency","A beverage manufacturer","A maker of electric fans"],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: \"Covered Bridge Industries has delayed the launch of its new Balmy Breeze soft drink\" (trì hoãn ra mắt loại nước giải khát mới) → soft drink = beverage → công ty sản xuất đồ uống.\n(A) Nhà sản xuất kem\n(B) Công ty quảng cáo\n(C) Nhà sản xuất đồ uống\n(D) Nhà sản xuất quạt điện"},{"n":156,"q":"Why did the leaders of Covered Bridge Industries not follow their original plan?","qvi":"Tại sao ban lãnh đạo của Covered Bridge Industries không thực hiện kế hoạch ban đầu?","opts":["They wanted to wait for more favorable market conditions.","Quality tests revealed several problems.","Their advertising campaign was not ready on time.","An essential ingredient was unavailable."],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: \"the delay was caused by a shortage of one of the drink’s main components, mango extract\" (sự trì hoãn là do thiếu hụt một thành phần chính — chiết xuất xoài) → main component = essential ingredient, shortage = unavailable.\n(A) Họ muốn chờ điều kiện thị trường thuận lợi hơn\n(B) Các bài kiểm tra chất lượng cho thấy nhiều vấn đề\n(C) Chiến dịch quảng cáo của họ chưa sẵn sàng đúng hạn\n(D) Một nguyên liệu thiết yếu không có sẵn"},{"n":157,"q":"During what month will Covered Bridge Industries most likely launch a new product?","qvi":"Trong tháng nào Covered Bridge Industries nhiều khả năng sẽ tung ra sản phẩm mới?","opts":["In June","In August","In November","In December"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: \"complete all quality testing by November so that it can launch the product the following month\" (hoàn tất kiểm tra chất lượng vào tháng 11 để ra mắt vào tháng tiếp theo) → tháng sau tháng 11 là tháng 12.\n(A) Tháng Sáu\n(B) Tháng Tám\n(C) Tháng Mười Một\n(D) Tháng Mười Hai"}]},{"ns":[158,160],"head":"Questions 158-160 refer to the following memo.","passages":["<h3>MEMO</h3><div class=\"hdr\"><p><b>From:</b> Leah Achen, Head of Technology Resources</p><p><b>To:</b> All Employees</p><p><b>Date:</b> June 28</p><p><b>Subject:</b> Video-editing software change</p></div><p>Effective July 20, employees will no longer have access to the Zipvid app for creating animated videos. — <span class=\"pos\">[1]</span> —. We will instead be using Curtain Call, which we trust will prove to be a more reliable program that is less likely to crash. — <span class=\"pos\">[2]</span> —. Employees who need to convert their videos from the format Zipvid uses to a format compatible with Curtain Call should install the converter utility to their work computers. This utility can be found in our company’s online software library. — <span class=\"pos\">[3]</span> —. For assistance with this process, please contact Manuel Costa in Technology Support. — <span class=\"pos\">[4]</span> —.</p>"],"vi":"BẢN GHI NHỚ\n\nTừ: Leah Achen, Trưởng bộ phận Tài nguyên Công nghệ\nGửi: Toàn thể nhân viên\nNgày: 28 tháng 6\nChủ đề: Thay đổi phần mềm chỉnh sửa video\n\nBắt đầu từ ngày 20 tháng 7, nhân viên sẽ không còn được truy cập vào ứng dụng Zipvid để tạo video hoạt hình nữa. — [1] — Thay vào đó, chúng ta sẽ sử dụng Curtain Call, một chương trình mà chúng tôi tin rằng sẽ đáng tin cậy hơn và ít gặp sự cố (bị treo) hơn. — [2] — Những nhân viên cần chuyển đổi video từ định dạng mà Zipvid sử dụng sang định dạng tương thích với Curtain Call nên cài đặt tiện ích chuyển đổi vào máy tính làm việc của mình. Tiện ích này có thể được tìm thấy trong thư viện phần mềm trực tuyến của công ty. — [3] — Để được hỗ trợ về quy trình này, vui lòng liên hệ Manuel Costa thuộc bộ phận Hỗ trợ Công nghệ. — [4] —","qs":[{"n":158,"q":"Why is the Zipvid app no longer being used?","qvi":"Tại sao ứng dụng Zipvid không còn được sử dụng nữa?","opts":["It is more expensive than similar programs.","It was used by only a few employees.","It malfunctioned too frequently.","It is not compatible with new computers."],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: \"We will instead be using Curtain Call, which we trust will prove to be a more reliable program that is less likely to crash\" (chương trình đáng tin cậy hơn và ít bị treo hơn) → ngụ ý Zipvid hay bị treo/trục trặc.\n(A) Nó đắt hơn các chương trình tương tự\n(B) Chỉ có một vài nhân viên sử dụng nó\n(C) Nó gặp trục trặc quá thường xuyên\n(D) Nó không tương thích với các máy tính mới"},{"n":159,"q":"According to the memo, what can Mr. Costa help employees do?","qvi":"Theo bản ghi nhớ, ông Costa có thể giúp nhân viên làm gì?","opts":["Convert videos","Recover lost data","Order software","Complete a form"],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: \"Employees who need to convert their videos ... For assistance with this process, please contact Manuel Costa\" (Để được hỗ trợ về quy trình này — tức chuyển đổi video — hãy liên hệ Manuel Costa).\n(A) Chuyển đổi video\n(B) Khôi phục dữ liệu bị mất\n(C) Đặt mua phần mềm\n(D) Hoàn thành một biểu mẫu"},{"n":160,"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n“It has already been installed on all work computers, so you can begin using it immediately.”","qvi":"Câu sau phù hợp nhất để đặt vào vị trí nào trong các vị trí được đánh dấu [1], [2], [3] và [4]?\n“Phần mềm này đã được cài đặt sẵn trên tất cả các máy tính làm việc, vì vậy bạn có thể bắt đầu sử dụng ngay.”","opts":["[1]","[2]","[3]","[4]"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: \"It\" phải chỉ phần mềm mới vừa được nhắc đến. Ngay trước [2] là câu giới thiệu Curtain Call (\"We will instead be using Curtain Call...\") → \"It has already been installed...\" = Curtain Call đã được cài sẵn. Ở [3] \"It\" sẽ chỉ tiện ích chuyển đổi, nhưng tiện ích này phải tự cài (should install) nên không hợp."}]},{"ns":[161,164],"head":"Questions 161-164 refer to the following article.","passages":["<h3>Local Businesses Thriving</h3><p>GREENWOOD (July 6)—Why a particular business succeeds is often a mystery, but a couple of local shops appear to have learned the secret. Two years after opening their doors, A Thousand Stories and Rosier’s Garden Center are flourishing.</p><p>“There was a lot of trial and error at the outset, but we finally figured it out,” said Liz Ohtani, who, together with Sandra Rivera, owns A Thousand Stories. “I manage the stock, and Sandra handles the public-facing part, including special events with authors.”</p><p>Ms. Rivera added, “We make a fantastic team. But I think our strongest asset is our supportive neighborhood. People here love books and reading, and they visit us regularly. We also have an active social media presence, and that helps too.”</p><p>Louie Rosier, owner of Rosier’s Garden Center, agreed that getting a business up and running takes effort and patience.</p><p>Mr. Rosier, whose store specializes in native plants and flowers, admitted that his first year with the garden center was tough. He recalled, “It took a long time to turn a profit. Sometimes I considered shutting it all down and going back to my former job.”</p><p>Despite the difficult start, Mr. Rosier persevered. Now that the business is doing well, he is exploring opening another store.</p><p>“I’d like to reach customers beyond the Greenwood area,” he said. “I’m currently looking at Morganville to see if that would be the best location for a second store.”</p>"],"vi":"Các Doanh Nghiệp Địa Phương Đang Phát Triển Mạnh\n\nGREENWOOD (ngày 6 tháng 7) — Lý do vì sao một doanh nghiệp cụ thể có thể thành công thường là điều khó lý giải, nhưng một vài cửa hàng địa phương dường như đã tìm ra bí quyết. Hai năm sau khi mở cửa, A Thousand Stories và Rosier’s Garden Center đang phát triển rất thuận lợi.\n\n“Ban đầu có rất nhiều thử nghiệm và sai sót, nhưng cuối cùng chúng tôi cũng tìm ra cách,” bà Liz Ohtani, đồng sở hữu A Thousand Stories cùng với Sandra Rivera, cho biết. “Tôi quản lý hàng hóa, còn Sandra phụ trách các hoạt động tiếp xúc với công chúng, bao gồm cả những sự kiện đặc biệt với các tác giả.”\n\nBà Rivera nói thêm: “Chúng tôi là một đội làm việc rất ăn ý. Nhưng tôi nghĩ thế mạnh lớn nhất của chúng tôi chính là khu dân cư luôn ủng hộ. Người dân ở đây yêu sách và việc đọc, vì vậy họ thường xuyên ghé thăm cửa hàng. Chúng tôi cũng có sự hiện diện tích cực trên mạng xã hội, và điều đó cũng rất hữu ích.”\n\nLouie Rosier, chủ của Rosier’s Garden Center, đồng ý rằng việc xây dựng và duy trì một doanh nghiệp đòi hỏi nhiều nỗ lực và sự kiên nhẫn.\n\nÔng Rosier, người điều hành cửa hàng chuyên về các loại cây và hoa bản địa, thừa nhận rằng năm đầu tiên kinh doanh trung tâm làm vườn của ông vô cùng khó khăn. Ông nhớ lại: “Phải mất một thời gian dài tôi mới có thể tạo ra lợi nhuận. Đôi lúc tôi đã nghĩ đến việc đóng cửa hoàn toàn và quay trở lại công việc cũ.”\n\nBất chấp khởi đầu gian nan, ông Rosier vẫn kiên trì. Giờ đây khi doanh nghiệp đang hoạt động tốt, ông đang cân nhắc việc mở thêm một cửa hàng nữa.\n\n“Tôi muốn tiếp cận khách hàng ngoài khu vực Greenwood,” ông nói. “Hiện tôi đang xem xét Morganville để xem đó có phải là địa điểm phù hợp nhất cho cửa hàng thứ hai hay không.”","qs":[{"n":161,"q":"What type of business do Ms. Ohtani and Ms. Rivera most likely operate?","qvi":"Bà Ohtani và bà Rivera nhiều khả năng điều hành loại hình doanh nghiệp nào?","opts":["A real estate office","An event planning service","A bookshop","A media company"],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Hai bà cùng sở hữu A Thousand Stories, tổ chức \"special events with authors\" (sự kiện với các tác giả) và \"People here love books and reading, and they visit us regularly\" (người dân yêu sách và việc đọc nên thường xuyên ghé cửa hàng) → hiệu sách.\n(A) Văn phòng bất động sản\n(B) Dịch vụ tổ chức sự kiện\n(C) Hiệu sách\n(D) Công ty truyền thông"},{"n":162,"q":"What is one similarity between A Thousand Stories and Rosier’s Garden Center?","qvi":"Một điểm giống nhau giữa A Thousand Stories và Rosier’s Garden Center là gì?","opts":["Both are operated by co-owners.","Both serve customers worldwide.","Both advertise primarily online.","Both struggled when they first opened."],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: A Thousand Stories: \"There was a lot of trial and error at the outset\" (ban đầu có nhiều thử nghiệm và sai sót). Rosier’s: \"his first year with the garden center was tough\" (năm đầu tiên vô cùng khó khăn) → cả hai đều khó khăn lúc mới mở. (A) sai vì Rosier’s chỉ có một chủ là Louie Rosier.\n(A) Cả hai đều do các đồng sở hữu điều hành\n(B) Cả hai phục vụ khách hàng trên toàn thế giới\n(C) Cả hai chủ yếu quảng cáo trực tuyến\n(D) Cả hai đều gặp khó khăn khi mới mở cửa"},{"n":163,"q":"The word “turn” in paragraph 5, line 4, is closest in meaning to","qvi":"Từ “turn” trong đoạn 5, dòng 4, gần nghĩa nhất với từ nào?","opts":["join","gain","change","reverse"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: \"It took a long time to turn a profit\" (Phải mất một thời gian dài mới tạo ra/có được lợi nhuận) → turn a profit = gain a profit (thu được lợi nhuận).\n(A) tham gia\n(B) đạt được\n(C) thay đổi\n(D) đảo ngược"},{"n":164,"q":"According to the article, what will Mr. Rosier most likely do soon?","qvi":"Theo bài báo, ông Rosier nhiều khả năng sẽ làm gì trong thời gian tới?","opts":["He will write a book about his experience.","He will move his home to Morganville.","He will return to his previous career.","He will open another garden center."],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: \"he is exploring opening another store\" và \"I’m currently looking at Morganville to see if that would be the best location for a second store\" (đang xem Morganville cho cửa hàng thứ hai) → sẽ mở thêm một trung tâm làm vườn. (B) sai vì Morganville là nơi đặt cửa hàng, không phải chuyển nhà.\n(A) Ông sẽ viết một cuốn sách về trải nghiệm của mình\n(B) Ông sẽ chuyển nhà đến Morganville\n(C) Ông sẽ quay lại nghề nghiệp trước đây\n(D) Ông sẽ mở thêm một trung tâm làm vườn khác"}]},{"ns":[165,167],"head":"Questions 165-167 refer to the following notice.","passages":["<h3>Important Information Regarding Employee Safety</h3><p>All employees are expected to follow the guidelines in the employee manual as well as posted safety rules. Certain jobs require employees to follow the additional safety guidelines provided by their supervisors. Because we take safety seriously, we urge any employee who becomes aware of a breach of these protocols to contact a supervisor or the safety coordinator. Further, any employee who has concerns about these protocols or would like to propose additional measures should contact the safety coordinator directly.</p><p>Additionally, contact information for employees who are trained in first aid can be found in the employee manual. Free first aid training and certification are available twice yearly to all employees. For more information about when trainings are held, please contact Lynn Schneider at lschneider@rinckindustry.com.</p>"],"vi":"Thông Tin Quan Trọng Liên Quan Đến An Toàn Nhân Viên\n\nTất cả nhân viên được yêu cầu tuân thủ các hướng dẫn trong sổ tay nhân viên cũng như các quy định an toàn được niêm yết. Một số vị trí công việc nhất định yêu cầu nhân viên phải tuân theo các hướng dẫn an toàn bổ sung do người quản lý trực tiếp cung cấp. Vì chúng tôi coi trọng vấn đề an toàn, chúng tôi khuyến khích bất kỳ nhân viên nào phát hiện ra việc vi phạm các quy trình an toàn này hãy liên hệ với người quản lý hoặc điều phối viên an toàn. Ngoài ra, bất kỳ nhân viên nào có thắc mắc về các quy trình này hoặc muốn đề xuất các biện pháp bổ sung nên liên hệ trực tiếp với điều phối viên an toàn.\n\nBên cạnh đó, thông tin liên hệ của những nhân viên đã được đào tạo sơ cứu có thể được tìm thấy trong sổ tay nhân viên. Công ty cung cấp khóa đào tạo và chứng nhận sơ cứu miễn phí hai lần mỗi năm cho toàn thể nhân viên. Để biết thêm thông tin về thời gian tổ chức các buổi đào tạo, vui lòng liên hệ Lynn Schneider qua địa chỉ email lschneider@rinckindustry.com.","qs":[{"n":165,"q":"What responsibility of a supervisor is mentioned in the notice?","qvi":"Trách nhiệm nào của người giám sát được đề cập trong thông báo?","opts":["Distributing employee manuals","Overseeing the work of the safety coordinator","Regularly updating the posted safety rules","Providing safety guidelines for specific jobs"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: \"Certain jobs require employees to follow the additional safety guidelines provided by their supervisors\" (Một số công việc nhất định yêu cầu tuân theo hướng dẫn an toàn bổ sung do người giám sát cung cấp) → certain jobs = specific jobs.\n(A) Phát sổ tay nhân viên\n(B) Giám sát công việc của điều phối viên an toàn\n(C) Thường xuyên cập nhật các quy định an toàn được niêm yết\n(D) Cung cấp hướng dẫn an toàn cho các công việc cụ thể"},{"n":166,"q":"The word “measures” in paragraph 1, line 6, is closest in meaning to","qvi":"Từ “measures” trong đoạn 1, dòng 6, gần nghĩa nhất với từ nào?","opts":["amounts","procedures","dimensions","penalties"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: \"would like to propose additional measures\" (muốn đề xuất thêm các biện pháp) — trong ngữ cảnh các quy trình an toàn (protocols), measures = biện pháp = procedures.\n(A) số lượng\n(B) biện pháp / quy trình\n(C) kích thước\n(D) hình phạt"},{"n":167,"q":"According to the notice, why should employees contact Ms. Schneider?","qvi":"Theo thông báo, tại sao nhân viên nên liên hệ với bà Schneider?","opts":["To apply for a new position","To update their contact information","To suggest additional safety rules","To request a training schedule"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: \"For more information about when trainings are held, please contact Lynn Schneider\" (Để biết thời gian tổ chức các buổi đào tạo, hãy liên hệ Lynn Schneider) → hỏi lịch đào tạo. (C) sai vì đề xuất biện pháp an toàn thì liên hệ điều phối viên an toàn.\n(A) Để ứng tuyển vào một vị trí mới\n(B) Để cập nhật thông tin liên lạc của họ\n(C) Để đề xuất thêm các quy định an toàn\n(D) Để yêu cầu lịch đào tạo"}]},{"ns":[168,171],"head":"Questions 168-171 refer to the following job description.","passages":["<h3>Dora County Department of Transportation<br>Division of Administrative Services</h3><h4>HIGHWAY SUPERVISOR</h4><p>The highway supervisor oversees all tasks related to the construction and maintenance of road-related structures throughout Dora County, including creating work objectives for all emergency program activities. Key responsibilities include the organization of all snow-removal operations and construction projects. — <span class=\"pos\">[1]</span> —. Therefore, the supervisor must also be able to perform construction and maintenance work as needed and possess an appropriate level of skill in operating the relevant equipment.</p><p>— <span class=\"pos\">[2]</span> —. The supervisor assists in the hiring and training of subordinates and works with division leaders to conduct evaluations and yearly performance reviews of crew members. Crucially, the supervisor instructs crew members in safety procedures and monitors the safety of works in progress. The supervisor informs the division director of major personnel problems; the director will recommend an appropriate course of action in all instances. — <span class=\"pos\">[3]</span> —. Significant concerns raised by employees are brought to the attention of division leaders by the supervisor, who functions as a liaison between crew members and the Division of Administrative Services.</p><p>Managing the division’s designated budget is a critical aspect of the position. The supervisor shows proficiency in the use of computers to keep track of the budget each month. — <span class=\"pos\">[4]</span> —. The supervisor prepares expenditure reports and time sheets as well as statistical and narrative reports related to maintenance and repair activities, being sure to record the amount of time, number of employees, and materials used for each activity.</p>"],"vi":"Sở Giao thông Quận Dora\nPhòng Dịch vụ Hành chính\n\nGIÁM SÁT ĐƯỜNG BỘ\n\nGiám sát đường bộ chịu trách nhiệm quản lý tất cả các nhiệm vụ liên quan đến xây dựng và bảo trì các công trình đường bộ trên toàn Quận Dora, bao gồm việc xây dựng mục tiêu công việc cho các hoạt động của chương trình ứng phó khẩn cấp. Các trách nhiệm chính bao gồm việc tổ chức toàn bộ hoạt động dọn tuyết và các dự án xây dựng. — [1] — Vì vậy, người giám sát cũng phải có khả năng trực tiếp thực hiện công việc xây dựng và bảo trì khi cần thiết và sở hữu trình độ kỹ năng phù hợp trong việc vận hành các thiết bị liên quan.\n\n— [2] — Người giám sát hỗ trợ trong việc tuyển dụng và đào tạo nhân viên cấp dưới, đồng thời làm việc với các lãnh đạo bộ phận để tiến hành đánh giá và xét duyệt hiệu suất hằng năm cho các thành viên trong đội. Quan trọng hơn, người giám sát hướng dẫn các thành viên về quy trình an toàn và giám sát mức độ an toàn của các công việc đang thực hiện. Người giám sát sẽ thông báo cho giám đốc bộ phận về các vấn đề nghiêm trọng liên quan đến nhân sự; giám đốc sẽ đề xuất biện pháp xử lý phù hợp trong mọi trường hợp. — [3] — Những mối quan ngại quan trọng do nhân viên nêu ra sẽ được người giám sát chuyển đến lãnh đạo bộ phận, với vai trò là cầu nối giữa các thành viên trong đội và Phòng Dịch vụ Hành chính.\n\nViệc quản lý ngân sách được phân bổ cho bộ phận là một khía cạnh then chốt của vị trí này. Người giám sát phải thành thạo trong việc sử dụng máy tính để theo dõi ngân sách hằng tháng. — [4] — Người giám sát chuẩn bị báo cáo chi tiêu và bảng chấm công, cũng như các báo cáo thống kê và báo cáo tường thuật liên quan đến hoạt động bảo trì và sửa chữa, đồng thời đảm bảo ghi lại thời gian, số lượng nhân viên và vật liệu được sử dụng cho từng hoạt động.","qs":[{"n":168,"q":"What is suggested about Dora County?","qvi":"Điều gì được gợi ý về quận Dora?","opts":["It gets cold enough to snow there.","It has a large population.","It purchases equipment from local vendors.","It has many four-lane highways."],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: \"Key responsibilities include the organization of all snow-removal operations\" (Trách nhiệm chính bao gồm tổ chức toàn bộ hoạt động dọn tuyết) → quận Dora có tuyết rơi.\n(A) Nơi đây đủ lạnh để có tuyết rơi\n(B) Nơi đây có dân số đông\n(C) Nơi đây mua thiết bị từ các nhà cung cấp địa phương\n(D) Nơi đây có nhiều đường cao tốc bốn làn"},{"n":169,"q":"According to the job description, what should the highway supervisor do if a serious problem with a crew member arises?","qvi":"Theo mô tả công việc, người giám sát đường bộ nên làm gì nếu phát sinh vấn đề nghiêm trọng với một thành viên trong đội?","opts":["Suggest a replacement worker.","Restrict the crew member’s activities.","Notify the division director of the issue.","Designate a liaison to explain the matter to management."],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: \"The supervisor informs the division director of major personnel problems\" (Người giám sát thông báo cho giám đốc bộ phận về các vấn đề nhân sự nghiêm trọng) → informs = notify, major personnel problems = serious problem with a crew member.\n(A) Đề xuất một công nhân thay thế\n(B) Hạn chế các hoạt động của thành viên đó\n(C) Thông báo vấn đề cho giám đốc bộ phận\n(D) Chỉ định một người liên lạc để giải thích vấn đề với ban quản lý"},{"n":170,"q":"What is NOT a responsibility of the highway supervisor?","qvi":"Điều nào KHÔNG phải là trách nhiệm của người giám sát đường bộ?","opts":["Operating construction equipment","Conducting yearly performance reviews","Managing the monthly budget","Negotiating crew member salaries"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: (A) \"possess an appropriate level of skill in operating the relevant equipment\"; (B) \"conduct evaluations and yearly performance reviews of crew members\"; (C) \"Managing the division’s designated budget... keep track of the budget each month\". Việc thương lượng lương không được nhắc đến → (D).\n(A) Vận hành thiết bị xây dựng\n(B) Thực hiện đánh giá hiệu suất hằng năm\n(C) Quản lý ngân sách hằng tháng\n(D) Thương lượng mức lương cho các thành viên trong đội"},{"n":171,"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n“The position features several duties related to staff management.”","qvi":"Câu sau phù hợp nhất để đặt vào vị trí nào trong các vị trí được đánh dấu [1], [2], [3] và [4]?\n“Vị trí này bao gồm nhiều nhiệm vụ liên quan đến việc quản lý nhân sự.”","opts":["[1]","[2]","[3]","[4]"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Vị trí [2] mở đầu đoạn 2 — đoạn nói toàn bộ về quản lý nhân sự: tuyển dụng và đào tạo cấp dưới, đánh giá hiệu suất, hướng dẫn an toàn cho thành viên, xử lý vấn đề nhân sự. Câu chèn đóng vai trò câu chủ đề giới thiệu đoạn này."}]},{"ns":[172,175],"head":"Questions 172-175 refer to the following text-message chain.","passages":["<div class=\"msg\"><p><b>Marcus Gollancz (3:18 P.M.)</b></p><p>Jennifer, can you be at the Browns’ house at 7:00 A.M. tomorrow to remove the furnace ductwork? Arthur’s foundation-repair crew will need to access that area of the crawl space under the house.</p></div><div class=\"msg\"><p><b>Jennifer Kaluza (3:20 P.M.)</b></p><p>OK, it should take me about an hour. That’s 210 Leon Drive, right?</p></div><div class=\"msg\"><p><b>Marcus Gollancz (3:20 P.M.)</b></p><p>That’s right.</p></div><div class=\"msg\"><p><b>Arthur Gruyter (3:21 P.M.)</b></p><p>My crew will be there to start work shortly after 8:00 A.M. tomorrow. Our work patching and waterproofing the foundation will likely take three or four days. It’s an unusually large job.</p></div><div class=\"msg\"><p><b>Jennifer Kaluza (3:22 P.M.)</b></p><p>So, when would you like me to come back to reinstall the ductwork?</p></div><div class=\"msg\"><p><b>Marcus Gollancz (3:23 P.M.)</b></p><p>The Browns are away on vacation, so I think Friday afternoon should be fine.</p></div><div class=\"msg\"><p><b>Jennifer Kaluza (3:23 P.M.)</b></p><p>I’m scheduled to work at Mr. Amadi’s apartment on Friday—can the Browns’ ductwork wait until Monday?</p></div><div class=\"msg\"><p><b>Marcus Gollancz (3:24 P.M.)</b></p><p>Sure. Early on Monday would work.</p></div><div class=\"msg\"><p><b>Jennifer Kaluza (3:25 P.M.)</b></p><p>You got it, Marcus.</p></div>"],"vi":"Marcus Gollancz (3:18 chiều): Jennifer, bạn có thể có mặt tại nhà của gia đình Brown lúc 7:00 sáng ngày mai để tháo hệ thống ống dẫn khí của lò sưởi không? Đội sửa chữa móng nhà của Arthur sẽ cần tiếp cận khu vực khoang trống dưới sàn nhà.\n\nJennifer Kaluza (3:20 chiều): Được thôi, chắc tôi sẽ mất khoảng một giờ (để làm việc đó). Địa chỉ là 210 Leon Drive, đúng không?\n\nMarcus Gollancz (3:20 chiều): Đúng rồi.\n\nArthur Gruyter (3:21 chiều): Đội của tôi sẽ đến đó và bắt đầu làm việc không lâu sau 8:00 sáng ngày mai. Công việc của chúng tôi là vá và chống thấm móng nhà, có thể sẽ mất ba hoặc bốn ngày. Đây là một công việc có quy mô lớn bất thường.\n\nJennifer Kaluza (3:22 chiều): Vậy khi nào anh muốn tôi quay lại để lắp đặt lại hệ thống ống dẫn khí?\n\nMarcus Gollancz (3:23 chiều): Gia đình Brown đang đi nghỉ, nên tôi nghĩ chiều thứ Sáu là được.\n\nJennifer Kaluza (3:23 chiều): Tôi đã có lịch làm việc tại căn hộ của ông Amadi vào thứ Sáu rồi — vậy hệ thống ống dẫn khí của nhà Brown có thể đợi đến thứ Hai được không?\n\nMarcus Gollancz (3:24 chiều): Được thôi. Sáng sớm thứ Hai là ổn.\n\nJennifer Kaluza (3:25 chiều): Rõ rồi, Marcus.","qs":[{"n":172,"q":"What is the purpose of the conversation?","qvi":"Mục đích của cuộc trò chuyện là gì?","opts":["To inform a homeowner about a construction project","To explain why a repair cannot be completed on time","To discuss the timing of a public event","To coordinate a work schedule"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: Cả cuộc trò chuyện là sắp xếp thời gian: Jennifer đến tháo ống lúc 7:00 sáng, đội của Arthur bắt đầu sau 8:00, rồi bàn ngày quay lại lắp đặt (thứ Sáu → thứ Hai) → điều phối lịch làm việc. (A) sai vì gia đình Brown (chủ nhà) không tham gia, họ đang đi nghỉ.\n(A) Thông báo cho chủ nhà về một dự án xây dựng\n(B) Giải thích vì sao việc sửa chữa không thể hoàn thành đúng hạn\n(C) Thảo luận thời gian tổ chức một sự kiện công cộng\n(D) Điều phối lịch làm việc"},{"n":173,"q":"What can be concluded about 210 Leon Drive?","qvi":"Có thể kết luận gì về 210 Leon Drive?","opts":["It is a private home.","It is an office building.","It is an apartment complex.","It is an industrial warehouse."],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: \"can you be at the Browns’ house...?\" — Jennifer hỏi \"That’s 210 Leon Drive, right?\" và Marcus xác nhận \"That’s right.\" → 210 Leon Drive là nhà của gia đình Brown (nhà riêng).\n(A) Là nhà riêng\n(B) Là tòa nhà văn phòng\n(C) Là khu căn hộ\n(D) Là kho công nghiệp"},{"n":174,"q":"What is suggested about the members of Mr. Gruyter’s work crew?","qvi":"Điều gì được gợi ý về đội làm việc của ông Gruyter?","opts":["They have added Ms. Kaluza to their group.","They are repairing Mr. Gollancz’ office.","They usually complete jobs in fewer than three days.","They have already begun work on Mr. Amadi’s apartment."],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: \"Our work ... will likely take three or four days. It’s an unusually large job.\" (có thể mất ba hoặc bốn ngày. Đây là một công việc lớn bất thường.) → bình thường công việc của họ nhỏ hơn, mất chưa đến ba ngày.\n(A) Họ đã thêm bà Kaluza vào nhóm\n(B) Họ đang sửa văn phòng của ông Gollancz\n(C) Họ thường hoàn thành công việc trong chưa đến ba ngày\n(D) Họ đã bắt đầu làm việc ở căn hộ của ông Amadi"},{"n":175,"q":"At 3:25 P.M., what does Ms. Kaluza most likely mean when she writes, “You got it”?","qvi":"Lúc 3:25 chiều, bà Kaluza nhiều khả năng có ý gì khi viết “You got it”?","opts":["She wants to confirm that Mr. Gollancz understands her.","She will be at 210 Leon Drive early Monday morning.","She will send Mr. Gruyter a bill for some work.","She hopes Mr. Gollancz will contact the Brown family."],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Jennifer hỏi \"can the Browns’ ductwork wait until Monday?\", Marcus đáp \"Sure. Early on Monday would work.\" (Sáng sớm thứ Hai là ổn) → \"You got it\" (Rõ rồi/Được thôi) = đồng ý sẽ đến nhà Brown (210 Leon Drive) vào sáng sớm thứ Hai.\n(A) Bà muốn xác nhận rằng ông Gollancz đã hiểu ý bà\n(B) Bà sẽ có mặt tại 210 Leon Drive vào sáng sớm thứ Hai\n(C) Bà sẽ gửi hóa đơn cho ông Gruyter cho một số công việc\n(D) Bà mong ông Gollancz sẽ liên hệ với gia đình Brown"}]},{"ns":[176,180],"head":"Questions 176-180 refer to the following Web page and e-mail.","passages":["<p>https://www.jjshomeandgarden.com/cementmixers</p><h3>JJ’s Home and Garden Suppliers</h3><h4>Cement Mixers</h4><table><tr><th>Model</th><th>Name</th><th>Description</th><th>Price</th></tr><tr><td>HCC-TX</td><td>Easy Star</td><td>• 2 cubic feet, 1 hp<br>• In-store pickup only</td><td>$189</td></tr><tr><td>CVY-XU</td><td>Mr. Buddy*</td><td>• 2 cubic feet, 5 hp<br>• Delivery only, 1–2 weeks</td><td>$359</td></tr><tr><td>PIT-RX</td><td>Concretizer</td><td>• 4 cubic feet, 3 hp<br>• In-store pickup and 5-day delivery</td><td>$499</td></tr><tr><td>HTK-LM</td><td>Big Mix</td><td>• 5 cubic feet, 5 hp<br>• In-store pickup only</td><td>$629</td></tr><tr><td>PPP-HT</td><td>Max for Pros</td><td>• 6 cubic feet, 7 hp<br>• Delivery only, 2–4 weeks</td><td>$949</td></tr></table><p>*Out of stock until July 26</p>","<div class=\"hdr\"><p><b>To:</b> Customer Service &lt;customerservice@jjshomeandgarden.com&gt;</p><p><b>From:</b> Marshall Weaver &lt;mweaver01@gomail.net&gt;</p><p><b>Date:</b> June 25</p><p><b>Subject:</b> Delayed order</p></div><p>Dear Customer Service Representative:</p><p>I received a confirmation e-mail on June 15 that my 4-cubic-foot cement mixer would be delivered one week ago from JJ’s Home and Garden Suppliers. I have a small business and am dependent on my equipment. I have not yet received the product, and I have already left several unanswered phone messages. If the cement mixer is not at my business by the end of the day today, I can still pick it up at either the New Gralen or the Paloner store if I have to, as I need it for a job tomorrow afternoon. If one is not available by tomorrow, I ask that you cancel my order and provide me with a full refund. I will instead buy a Mr. Buddy from Alliance Hardware Store, a small, local store where it is currently in stock (and at your same price).</p><p>Please advise me on the status of my order immediately. I hope that my order with you will arrive today and that no further action will be needed by either of us.</p><p>Sincerely,</p><p>Marshall Weaver</p>"],"vi":"TRANG WEB – https://www.jjshomeandgarden.com/cementmixers\nJJ’s Home and Garden Suppliers\nMáy trộn xi măng\n\nMã mẫu | Tên | Mô tả | Giá\nHCC-TX | Easy Star | Dung tích 2 feet khối, công suất 1 mã lực (hp); Chỉ nhận lấy hàng tại cửa hàng | 189 USD\nCVY-XU | Mr. Buddy* | Dung tích 2 feet khối, công suất 5 mã lực; Chỉ giao hàng, thời gian 1–2 tuần | 359 USD\nPIT-RX | Concretizer | Dung tích 4 feet khối, công suất 3 mã lực; Lấy tại cửa hàng hoặc giao hàng trong 5 ngày | 499 USD\nHTK-LM | Big Mix | Dung tích 5 feet khối, công suất 5 mã lực; Chỉ nhận lấy hàng tại cửa hàng | 629 USD\nPPP-HT | Max for Pros | Dung tích 6 feet khối, công suất 7 mã lực; Chỉ giao hàng, thời gian 2–4 tuần | 949 USD\n\n* Hết hàng cho đến ngày 26 tháng 7\n\nEMAIL\nGửi: Bộ phận Chăm sóc Khách hàng\nTừ: Marshall Weaver\nNgày: 25 tháng 6\nChủ đề: Đơn hàng bị giao trễ\n\nKính gửi Quý Nhân viên Chăm sóc Khách hàng,\n\nTôi đã nhận được e-mail xác nhận vào ngày 15 tháng 6 rằng chiếc máy trộn xi măng dung tích 4 feet khối của tôi sẽ được giao cách đây một tuần từ JJ’s Home and Garden Suppliers. Tôi điều hành một doanh nghiệp nhỏ và phụ thuộc vào thiết bị của mình. Cho đến nay tôi vẫn chưa nhận được sản phẩm, và tôi cũng đã để lại nhiều tin nhắn thoại nhưng không được hồi đáp. Nếu máy trộn xi măng không được giao đến doanh nghiệp của tôi trước khi kết thúc ngày hôm nay, tôi vẫn có thể đến nhận trực tiếp tại cửa hàng New Gralen hoặc Paloner nếu cần, vì tôi cần máy cho một công việc vào chiều ngày mai. Nếu đến ngày mai mà vẫn không có hàng, tôi đề nghị quý công ty hủy đơn hàng và hoàn lại toàn bộ số tiền cho tôi. Thay vào đó, tôi sẽ mua mẫu Mr. Buddy tại Alliance Hardware Store, một cửa hàng địa phương nhỏ nơi hiện đang có sẵn sản phẩm (và với cùng mức giá của quý công ty).\n\nXin vui lòng thông báo ngay cho tôi về tình trạng đơn hàng. Tôi hy vọng rằng đơn hàng của tôi sẽ được giao trong hôm nay và rằng không cần thêm bất kỳ hành động nào từ phía hai bên.\n\nTrân trọng,\nMarshall Weaver","qs":[{"n":176,"q":"What is indicated on the Web page?","qvi":"Trang web cho biết điều gì?","opts":["Big Mix is currently not available.","Mr. Buddy is the best-selling item.","Some items cannot be delivered.","All cement mixers have been discounted."],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Trang web: Easy Star và Big Mix đều ghi \"In-store pickup only\" (Chỉ nhận lấy hàng tại cửa hàng) → một số sản phẩm không được giao hàng. (A) sai: sản phẩm hết hàng là Mr. Buddy, không phải Big Mix.\n(A) Big Mix hiện không có sẵn\n(B) Mr. Buddy bán chạy nhất\n(C) Một số mặt hàng không thể giao\n(D) Tất cả máy trộn xi măng đang giảm giá"},{"n":177,"q":"What item did Mr. Weaver order from JJ’s Home and Garden Suppliers?","qvi":"Ông Weaver đã đặt mua sản phẩm nào từ JJ’s Home and Garden Suppliers?","opts":["Easy Star","Concretizer","Big Mix","Max for Pros"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Email: \"my 4-cubic-foot cement mixer would be delivered\" (máy trộn xi măng dung tích 4 feet khối của tôi sẽ được giao) + Trang web: Concretizer = \"4 cubic feet, 3 hp; In-store pickup and 5-day delivery\" → ông đặt Concretizer (câu hỏi kết hợp 2 đoạn).\n(A) Easy Star\n(B) Concretizer\n(C) Big Mix\n(D) Max for Pros"},{"n":178,"q":"In the e-mail, the word “full” in paragraph 1, line 7, is closest in meaning to","qvi":"Từ “full” trong email, đoạn 1, dòng 7, gần nghĩa nhất với","opts":["supplied","occupied","complete","abundant"],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Email: \"cancel my order and provide me with a full refund\" (hủy đơn hàng và hoàn lại toàn bộ số tiền cho tôi) → \"full refund\" = hoàn tiền đầy đủ, trọn vẹn → full = complete.\n(A) được cung cấp\n(B) kín / hết chỗ\n(C) hoàn chỉnh, trọn vẹn\n(D) dồi dào"},{"n":179,"q":"What is suggested about JJ's Home and Garden Suppliers?","qvi":"Điều gì được gợi ý về JJ’s Home and Garden Suppliers?","opts":["It specializes in the sale of large construction equipment.","It sells most of its products online.","It offers free delivery on all products.","It has stores in more than one location."],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: Email: \"I can still pick it up at either the New Gralen or the Paloner store\" (tôi vẫn có thể đến nhận tại cửa hàng New Gralen hoặc Paloner) → công ty có ít nhất hai cửa hàng.\n(A) Chuyên bán thiết bị xây dựng lớn\n(B) Bán phần lớn sản phẩm trực tuyến\n(C) Giao hàng miễn phí cho mọi sản phẩm\n(D) Có cửa hàng ở nhiều hơn một địa điểm"},{"n":180,"q":"What is the cost of a model CVY-XU cement mixer at Alliance Hardware Store?","qvi":"Giá máy trộn xi măng mẫu CVY-XU tại Alliance Hardware Store là bao nhiêu?","opts":["$189","$359","$499","$629"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Email: \"I will instead buy a Mr. Buddy from Alliance Hardware Store ... (and at your same price)\" (tôi sẽ mua Mr. Buddy tại Alliance Hardware Store ... với cùng mức giá của quý công ty) + Trang web: CVY-XU = Mr. Buddy, giá $359 → $359.\n(A) 189 đô la\n(B) 359 đô la\n(C) 499 đô la\n(D) 629 đô la"}]},{"ns":[181,185],"head":"Questions 181-185 refer to the following Web page and e-mail.","passages":["<p>https://www.collingswoodglobal.com/about</p><p><b>Home | About | Services | Contact Us</b></p><p>The international trade business can be complicated, especially if you are unfamiliar with the steps and documentation involved. Guidelines vary from country to country, and special licenses and permits may be needed.</p><p>Let the experienced consultants at Collingswood Global help! First, you will complete our short questionnaire about your business. Once we assess your needs, we will match you with one of our team members, listed below.</p><ul><li>Margaret Giordano: agricultural products</li><li>Jonah Woodrow: household appliances</li><li>Felicity Wong: precious stones</li><li>Malik Fadel: automotive parts</li></ul><p>We offer a single introductory session for $329 per hour. Your consultant will determine the rates for any subsequent sessions based on your needs. If you would like to receive guidance regularly, you would pay a monthly retainer at a cost to be negotiated during the introductory session.</p>","<p><b>E-Mail Message</b></p><div class=\"hdr\"><p><b>To:</b> contact@collingswoodglobal.com</p><p><b>From:</b> Sanjeev Yadav &lt;sanjeev.yadav@isvaraniltd.com&gt;</p><p><b>Date:</b> December 12</p><p><b>Subject:</b> Preconsultation questionnaire follow-up</p></div><p>To Whom It May Concern:</p><p>I filled out the questionnaire on your Web page, but I am not sure that my form went through. I never got a confirmation e-mail. As I mentioned in the form, we are a five-year-old company specializing in high-end washers and dryers. We sell our machines to stores all along the East Coast of the United States and are well-informed about domestic cargo procedures. However, we want to venture into international trade, particularly throughout Europe, and we would like ongoing support in this endeavor. Please contact me to discuss Isvarani Ltd.’s needs in more detail.</p><p>Many thanks,</p><p>Sanjeev Yadav, Owner, Isvarani Ltd.</p>"],"vi":"TRANG WEB – https://www.collingswoodglobal.com/about\nTrang chủ | Giới thiệu | Dịch vụ | Liên hệ\n\nHoạt động thương mại quốc tế có thể rất phức tạp, đặc biệt nếu bạn không quen thuộc với các quy trình và giấy tờ liên quan. Các hướng dẫn có thể khác nhau giữa các quốc gia, và có thể cần đến các giấy phép, giấy chứng nhận đặc biệt.\n\nHãy để đội ngũ tư vấn viên giàu kinh nghiệm của Collingswood Global hỗ trợ bạn! Trước tiên, bạn sẽ hoàn thành một bảng câu hỏi ngắn về doanh nghiệp của mình. Sau khi đánh giá nhu cầu của bạn, chúng tôi sẽ kết nối bạn với một thành viên phù hợp trong đội ngũ, được liệt kê bên dưới:\n\n• Margaret Giordano: sản phẩm nông nghiệp\n• Jonah Woodrow: thiết bị gia dụng\n• Felicity Wong: đá quý\n• Malik Fadel: phụ tùng ô tô\n\nChúng tôi cung cấp một buổi tư vấn giới thiệu ban đầu với mức phí 329 đô la Mỹ mỗi giờ. Chuyên viên tư vấn của bạn sẽ xác định mức phí cho các buổi làm việc tiếp theo dựa trên nhu cầu cụ thể của bạn. Nếu bạn muốn nhận được sự tư vấn thường xuyên, bạn sẽ thanh toán phí cố định hằng tháng, mức phí này sẽ được thương lượng trong buổi tư vấn ban đầu.\n\nEMAIL\nGửi đến: contact@collingswoodglobal.com\nTừ: Sanjeev Yadav <sanjeev.yadav@isvaraniltd.com>\nNgày: 12 tháng 12\nChủ đề: Theo dõi bảng câu hỏi trước buổi tư vấn\n\nKính gửi Quý vị,\n\nTôi đã điền vào bảng câu hỏi trên trang web của quý công ty, nhưng tôi không chắc rằng biểu mẫu của mình đã được gửi thành công. Tôi không nhận được email xác nhận nào. Như tôi đã đề cập trong biểu mẫu, chúng tôi là một công ty đã hoạt động được năm năm, chuyên về các dòng máy giặt và máy sấy cao cấp. Chúng tôi bán sản phẩm cho các cửa hàng trên khắp bờ Đông của Hoa Kỳ và rất am hiểu về quy trình vận chuyển hàng hóa trong nước. Tuy nhiên, chúng tôi mong muốn mở rộng sang lĩnh vực thương mại quốc tế, đặc biệt là trên toàn châu Âu, và chúng tôi muốn nhận được sự hỗ trợ thường xuyên trong quá trình này. Vui lòng liên hệ với tôi để thảo luận chi tiết hơn về nhu cầu của công ty Isvarani Ltd.\n\nXin chân thành cảm ơn,\nSanjeev Yadav, Chủ sở hữu, Isvarani Ltd.","qs":[{"n":181,"q":"What does the Web page indicate about guidelines for international trade?","qvi":"Trang web cho biết gì về các hướng dẫn thương mại quốc tế?","opts":["They are different for each country.","They often serve multiple purposes.","They are updated on a regular basis.","They are stricter than they once were."],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: Trang web: \"Guidelines vary from country to country\" (Các hướng dẫn khác nhau giữa các quốc gia) → vary from country to country = different for each country.\n(A) Khác nhau theo từng quốc gia\n(B) Thường phục vụ nhiều mục đích\n(C) Được cập nhật thường xuyên\n(D) Nghiêm ngặt hơn trước đây"},{"n":182,"q":"What does the Web page mention about the cost of a monthly retainer?","qvi":"Trang web nói gì về chi phí của phí duy trì (retainer) hằng tháng?","opts":["It cannot be negotiated.","It costs $329 per month.","It is set during an initial meeting.","It may be waived based on client needs."],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Trang web: \"you would pay a monthly retainer at a cost to be negotiated during the introductory session\" (phí hằng tháng sẽ được thương lượng trong buổi tư vấn ban đầu) → introductory session = initial meeting. (B) sai: $329 là phí mỗi giờ của buổi giới thiệu.\n(A) Không thể thương lượng\n(B) Có giá 329 đô la mỗi tháng\n(C) Được quyết định trong buổi gặp đầu tiên\n(D) Có thể được miễn tùy theo nhu cầu khách hàng"},{"n":183,"q":"Why does Mr. Yadav provide information about his company in the e-mail?","qvi":"Vì sao ông Yadav cung cấp thông tin về công ty mình trong email?","opts":["He is responding to a request from a prospective colleague.","He forgot to include the information on a form.","He is following an established process.","He is unsure whether a questionnaire he completed was received."],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: Email: \"I filled out the questionnaire on your Web page, but I am not sure that my form went through. I never got a confirmation e-mail.\" (Tôi đã điền bảng câu hỏi nhưng không chắc biểu mẫu đã được gửi thành công, tôi không nhận được email xác nhận) → nên ông nhắc lại thông tin công ty.\n(A) Ông đang trả lời yêu cầu từ một đồng nghiệp tương lai\n(B) Ông quên điền thông tin vào biểu mẫu\n(C) Ông đang làm theo một quy trình có sẵn\n(D) Ông không chắc bảng câu hỏi mình đã điền có được nhận hay chưa"},{"n":184,"q":"Who will Mr. Yadav most likely work with?","qvi":"Ông Yadav nhiều khả năng sẽ làm việc với ai?","opts":["Ms. Giordano","Mr. Woodrow","Ms. Wong","Mr. Fadel"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Email: \"we are a five-year-old company specializing in high-end washers and dryers\" (công ty chuyên máy giặt và máy sấy cao cấp) + Trang web: \"Jonah Woodrow: household appliances\" (thiết bị gia dụng) → máy giặt, máy sấy là thiết bị gia dụng → làm việc với ông Woodrow.\n(A) Bà Giordano\n(B) Ông Woodrow\n(C) Bà Wong\n(D) Ông Fadel"},{"n":185,"q":"What is mentioned in the e-mail about Isvarani Ltd.?","qvi":"Email đề cập gì về Isvarani Ltd.?","opts":["It wants its suppliers to remain confidential.","It violated an international policy by accident.","It has plans to expand its operations.","It needs more information about domestic cargo requirements."],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Email: \"we want to venture into international trade, particularly throughout Europe\" (chúng tôi mong muốn mở rộng sang thương mại quốc tế, đặc biệt là trên toàn châu Âu) → có kế hoạch mở rộng hoạt động. (D) sai: họ đã \"well-informed about domestic cargo procedures\".\n(A) Muốn giữ bí mật danh tính nhà cung cấp\n(B) Vô tình vi phạm một chính sách quốc tế\n(C) Có kế hoạch mở rộng hoạt động\n(D) Cần thêm thông tin về yêu cầu vận chuyển hàng trong nước"}]},{"ns":[186,190],"head":"Questions 186-190 refer to the following article, e-mail, and letter.","passages":["<h3>Customers’ Corner</h3><p>Customers’ Corner is a recurring feature in <i>Atlas Financial Review</i> (<i>AFR</i>) about customer-centric trends in Africa’s banking industry. This installment of the series discusses Sonfaya Mutual’s business advantage savings account (BASA).</p><p>Sonfaya Mutual’s BASA has an annual percentage yield of 2.2 percent, which is 1.6 percent higher than the yield of the business savings account offered by its nearest competitor. Moreover, it comes with a range of customer privileges, including yearly tax preparation with a certified tax accountant, one-on-one consultations with a dedicated account manager, and financial education programmes, both in-person and online. Except for the assistance with tax paperwork, these offerings are provided at no expense to BASA holders.</p><p>A minimum deposit of FRW 100,000 is required to open a BASA, while a monthly administration fee of FRW 1,500 is charged. For new BASA holders, the monthly cost is waived for the first six months. For more details, go to www.sonfayamutual.com/basa.</p><p>Sonfaya Mutual is headquartered in Kigali, Rwanda, with offices in the countries of Tanzania, Uganda, and Zambia. An in-depth article about Sonfaya Mutual’s origins, growth, and milestones was published in <i>AFR</i>’s January issue. Previous issues are at www.atlasfinancialreview.com/archives. Send questions about archived matters to archivist@atlasfinancialreview.com.</p>","<div class=\"hdr\"><p><b>To:</b> archivist@atlasfinancialreview.com</p><p><b>From:</b> ochabinga@mesuradobankofliberia.com.lr</p><p><b>Date:</b> 1 November</p><p><b>Subject:</b> Missing AFR issue</p></div><p>To Whom It May Concern:</p><p>I read the article on Sonfaya Mutual’s BASA in the most recent issue of <i>AFR</i> with interest. Subsequently, I visited your Web site, looking for the previous <i>AFR</i> issue referenced in the article. Unfortunately, I could not locate it on the archival page. Please advise on how I can obtain that back issue.</p><p>Sincerely,</p><p>Odette Chabinga<br>Vice President, Mesurado Bank of Liberia</p>","<p>23 November</p><p>Ms. Julienne Nirere<br>B.P. 2581<br>KIGALI</p><p>Dear Ms. Nirere,</p><p>Thank you for being a valued checking account holder with Sonfaya Mutual for fifteen years. We are, furthermore, pleased that you strengthened your relationship with us by opening a business advantage savings account (BASA).</p><p>Your checking and savings accounts are now joined, enabling you to transfer money from one account to the other online. Moreover, if you wish to withdraw funds from your BASA, you can use your debit card at any of our ATMs.</p><p>Finally, our recently launched online stock-trading platform, available to you at no charge, is excellent for allowing investors to manage their finances at their own pace. Contact our Wealth Management Department for details.</p><p>Sincerely,</p><p><i>Philbert Akamanzi</i></p><p>Philbert Akamanzi, Senior Accounts Manager</p>"],"vi":"BÀI BÁO – Góc Khách Hàng (Customers’ Corner)\n\nCustomers’ Corner là một chuyên mục định kỳ trên Atlas Financial Review (AFR), tập trung vào các xu hướng lấy khách hàng làm trung tâm trong ngành ngân hàng tại châu Phi. Kỳ này của loạt bài thảo luận về tài khoản tiết kiệm lợi thế dành cho doanh nghiệp (BASA) của Sonfaya Mutual.\n\nTài khoản BASA của Sonfaya Mutual có lãi suất hằng năm là 2,2%, cao hơn 1,6% so với lãi suất của tài khoản tiết kiệm doanh nghiệp do đối thủ cạnh tranh gần nhất cung cấp. Ngoài ra, tài khoản này còn đi kèm với nhiều đặc quyền dành cho khách hàng, bao gồm: dịch vụ chuẩn bị hồ sơ thuế hằng năm với một kế toán thuế được chứng nhận, các buổi tư vấn riêng với quản lý tài khoản chuyên trách, và các chương trình giáo dục tài chính, được tổ chức trực tiếp và trực tuyến. Ngoại trừ dịch vụ hỗ trợ về giấy tờ thuế, tất cả các quyền lợi này đều được cung cấp miễn phí cho người sở hữu tài khoản BASA.\n\nĐể mở một tài khoản BASA, khách hàng cần khoản tiền gửi tối thiểu là 100.000 FRW, và sẽ phải trả phí quản lý hằng tháng là 1.500 FRW. Đối với khách hàng BASA mới, phí hằng tháng sẽ được miễn trong sáu tháng đầu tiên. Để biết thêm chi tiết, vui lòng truy cập www.sonfayamutual.com/basa.\n\nSonfaya Mutual có trụ sở chính tại Kigali, Rwanda, và có văn phòng tại Tanzania, Uganda và Zambia. Một bài viết chuyên sâu về nguồn gốc, sự phát triển và các cột mốc của Sonfaya Mutual đã được đăng trong số tháng Một của AFR. Các số báo trước có tại www.atlasfinancialreview.com/archives. Mọi câu hỏi liên quan đến các tài liệu lưu trữ vui lòng gửi đến archivist@atlasfinancialreview.com.\n\nEMAIL\nGửi đến: archivist@atlasfinancialreview.com\nNgười gửi: ochabinga@mesuradobankofliberia.com.lr\nNgày: 1 tháng 11\nTiêu đề: Thiếu số báo AFR\n\nKính gửi Quý vị,\n\nTôi đã đọc bài viết về tài khoản BASA của Sonfaya Mutual trong số AFR mới nhất và thấy rất quan tâm. Sau đó, tôi đã truy cập trang web của quý vị để tìm số AFR trước đó được đề cập trong bài viết. Tuy nhiên, tôi không thể tìm thấy số báo này trên trang lưu trữ. Xin vui lòng cho tôi biết làm thế nào tôi có thể nhận được số báo cũ đó.\n\nTrân trọng,\nOdette Chabinga\nPhó Chủ tịch, Ngân hàng Mesurado của Liberia\n\nTHƯ\nNgày 23 tháng 11\n\nBà Julienne Nirere\nB.P. 2581\nKIGALI\n\nKính gửi bà Nirere,\n\nCảm ơn bà vì đã là khách hàng sở hữu tài khoản thanh toán của Sonfaya Mutual trong suốt mười lăm năm qua. Chúng tôi cũng rất vui mừng khi bà đã củng cố mối quan hệ với chúng tôi bằng việc mở thêm tài khoản tiết kiệm lợi thế kinh doanh (BASA).\n\nHiện nay, tài khoản thanh toán và tài khoản tiết kiệm của bà đã được liên kết, cho phép bà chuyển tiền trực tuyến giữa hai tài khoản. Hơn nữa, nếu bà muốn rút tiền từ tài khoản BASA, bà có thể sử dụng thẻ ghi nợ của mình tại bất kỳ máy ATM nào của chúng tôi.\n\nCuối cùng, nền tảng giao dịch chứng khoán trực tuyến mới được ra mắt gần đây của chúng tôi, được cung cấp miễn phí cho bà, là một công cụ tuyệt vời giúp các nhà đầu tư quản lý tài chính theo nhịp độ riêng của mình. Vui lòng liên hệ với Bộ phận Quản lý Tài sản của chúng tôi để biết thêm chi tiết.\n\nTrân trọng,\nPhilbert Akamanzi\nPhilbert Akamanzi, Quản lý Tài khoản Cao cấp","qs":[{"n":186,"q":"What is mentioned about Sonfaya Mutual’s financial education programs?","qvi":"Điều gì được đề cập về các chương trình giáo dục tài chính của Sonfaya Mutual?","opts":["They are offered for free.","They are held once a month.","They are led by account managers.","They are held in partnership with AFR."],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: Bài báo: \"...and financial education programmes, both in-person and online. Except for the assistance with tax paperwork, these offerings are provided at no expense to BASA holders.\" (Ngoại trừ hỗ trợ giấy tờ thuế, các quyền lợi này đều miễn phí) → at no expense = for free.\n(A) Được cung cấp miễn phí\n(B) Được tổ chức mỗi tháng một lần\n(C) Do quản lý tài khoản dẫn dắt\n(D) Được tổ chức với sự hợp tác của AFR"},{"n":187,"q":"What is indicated in the article about Sonfaya Mutual?","qvi":"Bài báo cho biết gì về Sonfaya Mutual?","opts":["It raised the amount for opening a BASA.","It will continue to add customer privileges.","It updated its Web site recently.","It is an international company."],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: Bài báo: \"Sonfaya Mutual is headquartered in Kigali, Rwanda, with offices in the countries of Tanzania, Uganda, and Zambia.\" (trụ sở ở Rwanda, có văn phòng ở Tanzania, Uganda, Zambia) → hoạt động ở nhiều quốc gia = công ty quốc tế.\n(A) Đã tăng số tiền tối thiểu để mở tài khoản BASA\n(B) Sẽ tiếp tục bổ sung quyền lợi khách hàng\n(C) Mới cập nhật trang web gần đây\n(D) Là một công ty quốc tế"},{"n":188,"q":"Why is Ms. Chabinga looking for a previous AFR issue?","qvi":"Vì sao bà Chabinga tìm một số báo AFR cũ?","opts":["To learn about the offerings of Sonfaya Mutual’s competitors","To know more about current customer-centric trends","To learn about the history of Sonfaya Mutual","To know more about Sonfaya Mutual’s BASA"],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Email: \"looking for the previous AFR issue referenced in the article\" (tìm số AFR trước đó được đề cập trong bài viết) + Bài báo: \"An in-depth article about Sonfaya Mutual’s origins, growth, and milestones was published in AFR’s January issue\" (bài viết về nguồn gốc, sự phát triển và các cột mốc của Sonfaya Mutual) → bà muốn tìm hiểu lịch sử công ty.\n(A) Để tìm hiểu các sản phẩm của đối thủ của Sonfaya Mutual\n(B) Để biết thêm về xu hướng lấy khách hàng làm trung tâm hiện nay\n(C) Để tìm hiểu lịch sử của Sonfaya Mutual\n(D) Để biết thêm về tài khoản BASA của Sonfaya Mutual"},{"n":189,"q":"What is suggested about Ms. Nirere?","qvi":"Điều gì được gợi ý về bà Nirere?","opts":["She will not have to pay the BASA monthly fee for six months.","She did not receive her debit card in a timely fashion.","She is a new Sonfaya Mutual customer.","She met with Mr. Akamanzi recently."],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: Thư: bà Nirere vừa \"opening a business advantage savings account (BASA)\" (mở thêm tài khoản BASA) + Bài báo: \"For new BASA holders, the monthly cost is waived for the first six months.\" (khách hàng BASA mới được miễn phí hằng tháng trong sáu tháng đầu) → bà được miễn phí 6 tháng. (C) sai: bà đã là khách hàng 15 năm.\n(A) Bà sẽ không phải trả phí BASA hằng tháng trong sáu tháng\n(B) Bà nhận thẻ ghi nợ không đúng hạn\n(C) Bà là khách hàng mới của Sonfaya Mutual\n(D) Bà vừa gặp ông Akamanzi gần đây"},{"n":190,"q":"What is a purpose of the letter?","qvi":"Một mục đích của bức thư là gì?","opts":["To explain the benefits of investing","To describe the options for managing funds","To explain how online stock trading works","To provide a department’s contact information"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Thư: \"enabling you to transfer money from one account to the other online\" (chuyển tiền trực tuyến giữa hai tài khoản), \"you can use your debit card at any of our ATMs\" (rút tiền bằng thẻ ghi nợ tại ATM), \"online stock-trading platform ... allowing investors to manage their finances\" (nền tảng giao dịch chứng khoán giúp quản lý tài chính) → thư mô tả các cách quản lý tiền.\n(A) Giải thích lợi ích của việc đầu tư\n(B) Mô tả các lựa chọn để quản lý tiền\n(C) Giải thích cách giao dịch cổ phiếu trực tuyến hoạt động\n(D) Cung cấp thông tin liên hệ của một bộ phận"}]},{"ns":[191,195],"head":"Questions 191-195 refer to the following e-mail, form, and receipt.","passages":["<div class=\"hdr\"><p><b>To:</b> Valley Road Bed and Breakfast &lt;info@valleyroadbandb.com&gt;</p><p><b>From:</b> Maya Rodriguez &lt;m.rodriguez@intermountaingraphics.com&gt;</p><p><b>Date:</b> March 30</p><p><b>Subject:</b> Breakfast schedule</p></div><p>Hello,</p><p>I have a reservation to stay at your bed and breakfast next week. I wanted to inquire about breakfast times. I need to leave before 7 A.M. on Saturday morning, April 11, for my conference at the Ivor Hotel and Conference Center. Will breakfast be available before then? If not, what restaurants near the conference would you recommend that would be open at that time?</p><p>Sincerely,</p><p>Maya Rodriguez</p>","<h3>Intermountain Graphics Travel Expense Reimbursement Form</h3><p>All Intermountain Graphics employees who travel on official company business must fill out a Travel Expense Reimbursement Form and upload their receipts within 30 days of travel in TravelNow, our electronic travel reimbursement system. All forms must be approved and signed by the employee’s department manager.</p><p><b>Employee:</b> Maya Rodriguez&nbsp;&nbsp;&nbsp;&nbsp;<b>Date:</b> April 28</p><p><b>Purpose of Trip:</b> To attend the Digital Graphic Designers Conference</p><table><tr><th>Date</th><th>Category</th><th>Description</th><th>Total</th></tr><tr><td>April 10</td><td>Transportation</td><td>Flight to/from San Jose International Airport</td><td>$230.00</td></tr><tr><td>April 10</td><td>Transportation</td><td>Taxi to Valley Road Bed and Breakfast</td><td>$31.00</td></tr><tr><td>April 11</td><td>Transportation</td><td>Taxi to the Ivor Hotel and Conference Center</td><td>$22.50</td></tr><tr><td>April 11</td><td>Meals</td><td>Breakfast at Eileen’s Diner</td><td>$23.85</td></tr><tr><td>April 11</td><td>Other</td><td>Conference Registration</td><td>$175.00</td></tr><tr><td>April 11</td><td>Meals</td><td>Dinner at Antonio’s</td><td>$48.67</td></tr><tr><td>April 12</td><td>Lodging</td><td>Valley Road Bed and Breakfast, two nights</td><td>$299.00</td></tr><tr><td>April 12</td><td>Transportation</td><td>Taxi to the San Jose International Airport</td><td>$31.00</td></tr><tr><td></td><td></td><td><b>Total amount to be reimbursed</b></td><td><b>$861.02</b></td></tr></table><p><b>Approved by</b> Eun Park&nbsp;&nbsp;&nbsp;&nbsp;<b>Signature</b> <i>Eun Park</i></p>","<h3>Eileen’s Diner</h3><p>Located in the Ivor Hotel and Conference Center</p><p>Family-owned and operated for over two decades!<br>1000 Mission Rico Blvd.<br>Santa Clara, CA 95054<br>(408) 555-0126</p><p>Saturday, April 11, 6:46 A.M.</p><table><tr><td>Breakfast Sandwich</td><td>$14.99</td></tr><tr><td>Coffee</td><td>$3.50</td></tr><tr><td>Subtotal</td><td>$18.49</td></tr><tr><td>Tax</td><td>$1.11</td></tr><tr><td>Total owed:</td><td>$19.60</td></tr><tr><td>Tip</td><td>$4.25</td></tr><tr><td><b>Total paid:</b></td><td><b>$23.85</b></td></tr></table><p>Credit Card: XXXXXXXXXXXX5348<br>Customer Name: Maya Rodriguez</p><p>***Customer Copy***</p>"],"vi":"EMAIL\nGửi: Valley Road Bed and Breakfast <info@valleyroadbandb.com>\nTừ: Maya Rodriguez <m.rodriguez@intermountaingraphics.com>\nNgày: 30 tháng 3\nChủ đề: Lịch phục vụ bữa sáng\n\nXin chào,\n\nTôi có một đặt phòng lưu trú tại nhà nghỉ của quý vị vào tuần tới. Tôi muốn hỏi về thời gian phục vụ bữa sáng. Tôi cần rời đi trước 7 giờ sáng vào sáng thứ Bảy, ngày 11 tháng 4, để tham dự hội nghị của mình tại Khách sạn và Trung tâm Hội nghị Ivor. Bữa sáng có được phục vụ trước thời điểm đó không? Nếu không, quý vị có thể đề xuất những nhà hàng nào gần trung tâm hội nghị mà sẽ mở cửa vào thời gian đó không?\n\nTrân trọng,\nMaya Rodriguez\n\nMẪU ĐƠN HOÀN TRẢ CHI PHÍ ĐI CÔNG TÁC – Intermountain Graphics\n\nTất cả nhân viên của Intermountain Graphics đi công tác chính thức cho công ty phải điền Mẫu đơn hoàn trả chi phí đi lại và tải hóa đơn lên hệ thống hoàn trả chi phí điện tử TravelNow trong vòng 30 ngày kể từ ngày đi công tác. Tất cả các mẫu đơn phải được trưởng bộ phận của nhân viên phê duyệt và ký tên.\n\nNhân viên: Maya Rodriguez – Ngày: 28 tháng 4\nMục đích chuyến đi: Tham dự Hội nghị Thiết kế Đồ họa Kỹ thuật số\n\nNgày | Loại chi phí | Mô tả | Tổng\n10/4 | Di chuyển | Vé máy bay đi/đến Sân bay Quốc tế San Jose | $230.00\n10/4 | Di chuyển | Taxi đến Valley Road Bed and Breakfast | $31.00\n11/4 | Di chuyển | Taxi đến Khách sạn & Trung tâm Hội nghị Ivor | $22.50\n11/4 | Ăn uống | Bữa sáng tại Eileen’s Diner | $23.85\n11/4 | Khác | Phí đăng ký hội nghị | $175.00\n11/4 | Ăn uống | Bữa tối tại Antonio’s | $48.67\n12/4 | Lưu trú | Valley Road Bed and Breakfast, 2 đêm | $299.00\n12/4 | Di chuyển | Taxi đến Sân bay Quốc tế San Jose | $31.00\nTổng số tiền được hoàn trả: $861.02\n\nNgười phê duyệt: Eun Park – Chữ ký: Eun Park\n\nHÓA ĐƠN – Eileen’s Diner\nNằm trong Khách sạn và Trung tâm Hội nghị Ivor\nDo gia đình sở hữu và điều hành hơn 20 năm!\n1000 Mission Rico Blvd., Santa Clara, CA 95054\n(408) 555-0126\n\nThứ Bảy, ngày 11 tháng 4, 6:46 sáng\nBánh mì kẹp ăn sáng: $14.99\nCà phê: $3.50\nTạm tính: $18.49\nThuế: $1.11\nTổng cộng: $19.60\nTiền tip: $4.25\nTổng đã thanh toán: $23.85\n\nThẻ tín dụng: XXXXXXXXXXXX5348\nTên khách hàng: Maya Rodriguez\n***Bản sao dành cho khách hàng***","qs":[{"n":191,"q":"What can be concluded about Valley Road Bed and Breakfast?","qvi":"Có thể kết luận gì về Valley Road Bed and Breakfast?","opts":["It does not serve breakfast before 7:00 A.M.","It provides a shuttle service to the airport.","It is located next to the Ivor Hotel and Conference Center.","It is no longer accepting reservations for April."],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: Email: \"I need to leave before 7 A.M. ... Will breakfast be available before then?\" (Bữa sáng có được phục vụ trước 7 giờ không?) + Biểu mẫu & hóa đơn: ngày 11/4 bà ăn sáng tại Eileen’s Diner lúc 6:46 sáng → nhà nghỉ không phục vụ bữa sáng trước 7 giờ (câu hỏi kết hợp 3 đoạn). (B) sai: bà đi taxi ra sân bay.\n(A) Không phục vụ bữa sáng trước 7 giờ sáng\n(B) Có dịch vụ xe đưa đón ra sân bay\n(C) Nằm cạnh Khách sạn và Trung tâm Hội nghị Ivor\n(D) Không còn nhận đặt phòng cho tháng Tư"},{"n":192,"q":"According to the form, what are employees expected to do?","qvi":"Theo biểu mẫu, nhân viên được yêu cầu làm gì?","opts":["Seek permission to travel from the finance department","Present their work at a conference","E-mail expense reports to a manager","Submit receipts within 30 days of travel"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: Biểu mẫu: \"must fill out a Travel Expense Reimbursement Form and upload their receipts within 30 days of travel in TravelNow\" (phải điền mẫu đơn và tải hóa đơn lên trong vòng 30 ngày kể từ chuyến đi) → upload receipts = submit receipts.\n(A) Xin phép phòng tài chính trước khi đi công tác\n(B) Trình bày công việc tại hội nghị\n(C) Gửi báo cáo chi phí qua email cho quản lý\n(D) Nộp hóa đơn trong vòng 30 ngày kể từ chuyến đi"},{"n":193,"q":"What is most likely true about the Digital Graphic Designers Conference?","qvi":"Điều gì nhiều khả năng đúng về Hội nghị Digital Graphic Designers?","opts":["It lasted three days.","It began on April 28.","It was held in Santa Clara.","It provided meals to participants."],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Email: hội nghị diễn ra \"at the Ivor Hotel and Conference Center\" + Hóa đơn: Eileen’s Diner \"Located in the Ivor Hotel and Conference Center ... Santa Clara, CA 95054\" → hội nghị được tổ chức tại Santa Clara. (B) sai: 28/4 là ngày điền biểu mẫu.\n(A) Kéo dài ba ngày\n(B) Bắt đầu vào ngày 28 tháng 4\n(C) Được tổ chức tại Santa Clara\n(D) Cung cấp bữa ăn cho người tham dự"},{"n":194,"q":"Based on the form, what is true about Ms. Park?","qvi":"Dựa vào biểu mẫu, điều gì đúng về bà Park?","opts":["She is a financial analyst.","She organizes conferences.","She is a department manager.","She owns a bed-and-breakfast."],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Biểu mẫu: \"All forms must be approved and signed by the employee’s department manager.\" (Mọi mẫu đơn phải được trưởng bộ phận phê duyệt và ký) + \"Approved by Eun Park – Signature Eun Park\" → bà Park là trưởng bộ phận.\n(A) Bà là nhà phân tích tài chính\n(B) Bà tổ chức các hội nghị\n(C) Bà là trưởng bộ phận\n(D) Bà sở hữu một nhà nghỉ"},{"n":195,"q":"What is indicated on the receipt about Eileen’s Diner?","qvi":"Hóa đơn cho biết gì về Eileen’s Diner?","opts":["It is open 24 hours a day.","It offers daily breakfast specials.","It has locations around the country.","It has been in business for more than twenty years."],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: Hóa đơn: \"Family-owned and operated for over two decades!\" (Do gia đình sở hữu và điều hành hơn hai thập kỷ) → over two decades = more than twenty years.\n(A) Mở cửa 24 giờ mỗi ngày\n(B) Có món ăn sáng đặc biệt mỗi ngày\n(C) Có chi nhánh trên khắp cả nước\n(D) Đã kinh doanh hơn hai mươi năm"}]},{"ns":[196,200],"head":"Questions 196-200 refer to the following e-mails and report.","passages":["<div class=\"hdr\"><p><b>To:</b> Jae-Jun Nahm</p><p><b>From:</b> Stacy Landon</p><p><b>Date:</b> May 4</p><p><b>Subject:</b> Quinar 5000</p></div><p>Jae-Jun,</p><p>The Quinar 5000 in Building F is not working properly. It does not run at a steady speed and requires constant attention from line workers. It was checked at the monthly inspection and received an acceptable rating. However, it is now slowing production throughout Building F. I believe it may fail completely unless it is looked at very soon.</p><p>Please send a technician to check it as soon as possible, since the production schedule will likely need to be adapted because of downtime during the service visit.</p><p>Thank you.</p><p>Stacy Landon<br>Production Manager</p>","<div class=\"hdr\"><p><b>To:</b> Stacy Landon</p><p><b>Cc:</b> Alex Nadiner</p><p><b>From:</b> Jae-Jun Nahm</p><p><b>Date:</b> May 4</p><p><b>Subject:</b> RE: Quinar 5000</p></div><p>Stacy,</p><p>Unfortunately, our internal equipment repair schedule is beyond capacity, so I am bringing on some new technicians next week. Meanwhile, I have authorized Konner Services to send one of their technicians to inspect the machine and make any necessary repairs. We have used this company before, and they are excellent. They will send someone tomorrow between 1:00 and 2:00 P.M. They informed me that the equipment may be down for up to two hours because of testing. Since I know there is a large shipment of product due to Altran Motors next week, I took the liberty of copying Alex Nadiner, who may need to assign some line workers to put in overtime to make up for the delay.</p><p>Jae-Jun Nahm<br>Director of Maintenance</p>","<h3>Konner Services Inspection and Repair Report</h3><table><tr><td><b>Machine:</b></td><td>Quinar 5000</td></tr><tr><td><b>Location:</b></td><td>Haverford Industries, 837 West Lorrie Street, Building F</td></tr><tr><td><b>Date of inspection:</b></td><td>May 5</td></tr><tr><td><b>Labor charges:</b></td><td>2.5 hours</td></tr></table><h4>Results:</h4><table><tr><td><b>Test 102:</b></td><td>Acceptable</td></tr><tr><td><b>Test 393:</b></td><td>Cleaning needed</td></tr><tr><td><b>Test 477:</b></td><td>Faulty Baum X33 main switch</td></tr><tr><td><b>Test 488:</b></td><td>Worn belts and hoses</td></tr><tr><td><b>Fluid levels:</b></td><td>Good</td></tr><tr><td><b>Gauges:</b></td><td>Good</td></tr></table><p><b>Comments:</b> The technician cleaned the machinery and replaced the malfunctioning switch. However, the belts and hoses should be replaced soon, which will require shutting down the line for about four hours. The line manager has been advised of this situation so that personnel can be reassigned accordingly during this repair.</p>"],"vi":"EMAIL 1\nGửi: Jae-Jun Nahm\nTừ: Stacy Landon\nNgày: 4 tháng 5\nChủ đề: Quinar 5000\n\nJae-Jun thân mến,\n\nMáy Quinar 5000 ở Tòa nhà F hiện đang hoạt động không đúng cách. Máy không chạy với tốc độ ổn định và cần sự theo dõi liên tục từ các công nhân dây chuyền. Máy đã được kiểm tra trong đợt kiểm tra định kỳ hằng tháng và được đánh giá là đạt yêu cầu. Tuy nhiên, hiện tại máy đang làm chậm quá trình sản xuất trên toàn bộ Tòa nhà F. Tôi tin rằng máy có thể sẽ hỏng hoàn toàn nếu không được kiểm tra trong thời gian rất sớm.\n\nVui lòng cử một kỹ thuật viên đến kiểm tra máy sớm nhất có thể, vì lịch sản xuất rất có thể sẽ cần được điều chỉnh do thời gian ngừng hoạt động trong quá trình bảo trì.\n\nXin cảm ơn.\nStacy Landon\nQuản lý Sản xuất\n\nEMAIL 2 (Trả lời)\nGửi: Stacy Landon\nCc: Alex Nadiner\nTừ: Jae-Jun Nahm\nNgày: 4 tháng 5\nChủ đề: RE: Quinar 5000\n\nStacy thân mến,\n\nRất tiếc, lịch sửa chữa thiết bị nội bộ của chúng ta hiện đã quá tải, vì vậy tôi sẽ bổ sung thêm một số kỹ thuật viên mới vào tuần tới. Trong thời gian chờ đợi, tôi đã cho phép công ty Konner Services cử một kỹ thuật viên đến kiểm tra máy và thực hiện các sửa chữa cần thiết. Chúng ta đã từng sử dụng dịch vụ của công ty này trước đây và họ làm việc rất tốt. Họ sẽ cử người đến vào ngày mai trong khoảng từ 1:00 đến 2:00 chiều. Họ cho biết thiết bị có thể phải ngừng hoạt động tối đa hai giờ để tiến hành kiểm tra. Vì tôi biết rằng tuần tới sẽ có một lô hàng lớn phải giao cho Altran Motors, nên tôi đã chủ động gửi bản sao e-mail này cho Alex Nadiner, người có thể cần sắp xếp cho một số công nhân làm thêm giờ để bù lại sự chậm trễ.\n\nJae-Jun Nahm\nGiám đốc Bảo trì\n\nBÁO CÁO KIỂM TRA VÀ SỬA CHỮA CỦA KONNER SERVICES\nMáy: Quinar 5000\nĐịa điểm: Haverford Industries, 837 West Lorrie Street, Tòa nhà F\nNgày kiểm tra: 5 tháng 5\nThời gian lao động: 2,5 giờ\n\nKết quả kiểm tra:\n• Bài kiểm tra 102: Đạt yêu cầu\n• Bài kiểm tra 393: Cần vệ sinh\n• Bài kiểm tra 477: Công tắc chính Baum X33 bị lỗi\n• Bài kiểm tra 488: Dây curoa và ống dẫn bị mòn\n• Mức chất lỏng: Tốt\n• Đồng hồ đo: Tốt\n\nNhận xét: Kỹ thuật viên đã vệ sinh máy móc và thay thế công tắc bị hỏng. Tuy nhiên, dây curoa và ống dẫn nên được thay thế sớm, việc này sẽ yêu cầu dừng dây chuyền sản xuất trong khoảng bốn giờ. Quản lý dây chuyền đã được thông báo về tình trạng này để có thể sắp xếp lại nhân sự phù hợp trong thời gian sửa chữa.","qs":[{"n":196,"q":"What is the purpose of the first e-mail?","qvi":"Mục đích của email đầu tiên là gì?","opts":["To verify an equipment order","To request machinery repair","To report on a monthly inspection","To encourage increased production"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Email 1: \"The Quinar 5000 in Building F is not working properly ... Please send a technician to check it as soon as possible\" (Máy không hoạt động đúng cách ... vui lòng cử kỹ thuật viên đến kiểm tra sớm nhất có thể) → yêu cầu sửa máy.\n(A) Xác nhận một đơn đặt thiết bị\n(B) Yêu cầu sửa chữa máy móc\n(C) Báo cáo về đợt kiểm tra hằng tháng\n(D) Khuyến khích tăng sản lượng"},{"n":197,"q":"What has Mr. Nahm decided to do to solve the problem in Building F?","qvi":"Ông Nahm đã quyết định làm gì để giải quyết vấn đề ở Tòa nhà F?","opts":["Employ additional workers","Hire an outside company","Lease a new building","Purchase a new machine"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Email 2: \"our internal equipment repair schedule is beyond capacity ... I have authorized Konner Services to send one of their technicians to inspect the machine and make any necessary repairs\" (lịch sửa chữa nội bộ quá tải, tôi đã cho phép công ty Konner Services cử kỹ thuật viên đến) → thuê công ty bên ngoài.\n(A) Thuê thêm công nhân\n(B) Thuê một công ty bên ngoài\n(C) Thuê một tòa nhà mới\n(D) Mua một máy mới"},{"n":198,"q":"Who most likely is Mr. Nadiner?","qvi":"Ông Nadiner nhiều khả năng là ai?","opts":["The director of maintenance","The lead technician","A line worker","A line manager"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: Email 2: \"I took the liberty of copying Alex Nadiner, who may need to assign some line workers to put in overtime\" (ông Nadiner có thể cần sắp xếp công nhân dây chuyền làm thêm giờ) + Báo cáo: \"The line manager has been advised of this situation so that personnel can be reassigned\" (Quản lý dây chuyền đã được thông báo để sắp xếp lại nhân sự) → người phân công công nhân dây chuyền là quản lý dây chuyền. (A) sai: giám đốc bảo trì là ông Nahm.\n(A) Giám đốc bảo trì\n(B) Kỹ thuật viên trưởng\n(C) Một công nhân dây chuyền\n(D) Một quản lý dây chuyền"},{"n":199,"q":"What company does Ms. Landon most likely work for?","qvi":"Bà Landon nhiều khả năng làm việc cho công ty nào?","opts":["Quinar Machines","Altran Motors","Konner Services","Haverford Industries"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: Email 1: bà Landon (Production Manager) viết về \"The Quinar 5000 in Building F\" + Báo cáo: \"Location: Haverford Industries, 837 West Lorrie Street, Building F\" → máy ở Tòa nhà F của Haverford Industries → bà làm việc cho Haverford Industries. (A) Quinar 5000 là tên máy; (B) Altran Motors là khách hàng nhận hàng; (C) Konner Services là công ty sửa chữa bên ngoài.\n(A) Quinar Machines\n(B) Altran Motors\n(C) Konner Services\n(D) Haverford Industries"},{"n":200,"q":"Based on the report, what test resulted in the replacement of a machine part?","qvi":"Dựa vào báo cáo, bài kiểm tra nào dẫn đến việc thay thế một linh kiện máy?","opts":["102","393","477","488"],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Báo cáo: \"Test 477: Faulty Baum X33 main switch\" (công tắc chính bị lỗi) + \"The technician cleaned the machinery and replaced the malfunctioning switch.\" (kỹ thuật viên đã thay công tắc bị hỏng) → Test 477. (D) sai: dây curoa và ống dẫn (Test 488) chỉ \"should be replaced soon\", chưa được thay.\n(A) 102\n(B) 393\n(C) 477\n(D) 488"}]}]}};
